import{d as I,C as l,o as D,c as R,a3 as i,E as a,j as n,a as e}from"./chunks/framework.Q4yG9rk_.js";const F=JSON.parse('{"title":"庄子·田子方","description":"从东郭顺子的缘而葆真、温伯雪子的目击道存，到孔子与老聃论游心、儒服与儒道，理解真实成就如何不止于言说、仪容与名位。","frontmatter":{"title":"庄子·田子方","description":"从东郭顺子的缘而葆真、温伯雪子的目击道存，到孔子与老聃论游心、儒服与儒道，理解真实成就如何不止于言说、仪容与名位。","category":"guide","aliases":["田子方","庄子田子方","zhuangzi chapter 21"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-21.md","filePath":"daoism/zhuang-zi/chapter-21.md","lastUpdated":1792641266000}'),N={name:"daoism/zhuang-zi/chapter-21.md"},L=I({...N,setup(E){const o=[{id:"tzf_teacher_s1",label:"田子方数称谿工：称道数当",sentences:[[{text:"田子方",glossary:"tzf_teacher_zifang"},"侍坐于魏文侯，",{text:"数称谿工",glossary:"tzf_teacher_xigong"},"。"],["文侯曰：「谿工，子之师邪？」"],["子方曰：「非也，",{text:"无择",glossary:"tzf_teacher_wuze"},"之里人也。称道数当，故无择称之。」"]]},{id:"tzf_teacher_s2",label:"真正的老师：东郭顺子",sentences:[["文侯曰：「然则子无师邪？」子方曰：「有。」"],["曰：「子之师谁邪？」子方曰：「",{text:"东郭顺子",glossary:"tzf_teacher_shunzi"},"。」"],["文侯曰：「然则夫子何故未尝称之？」"]]},{id:"tzf_teacher_s3",label:"人貌而天虚，缘而葆真，清而容物",sentences:[["子方曰：「其为人也真。",{text:"人貌而天虚",glossary:"tzf_teacher_tianxu"},"，",{text:"缘而葆真",glossary:"tzf_teacher_baozhen"},"，",{text:"清而容物",glossary:"tzf_teacher_rongwu"},"。"],["物无道，",{text:"正容以悟之",glossary:"tzf_teacher_zhengrong"},"，使人之意也消。无择何足以称之！」"]]},{id:"tzf_teacher_s4",label:"文侯之叹：夫魏真为我累耳",sentences:[["子方出，文侯",{text:"傥然",glossary:"tzf_teacher_tangran"},"，终日不言。召前立臣而语之曰：「远矣，",{text:"全德之君子",glossary:"tzf_teacher_quande"},"！"],["始吾以圣知之言、仁义之行为至矣。吾闻子方之师，吾形解而不欲动，口钳而不欲言。"],["吾所学者，直",{text:"土埂",glossary:"tzf_teacher_tugeng"},"耳！夫魏真为我累耳！」"]]}],p=[{id:"tzf_teacher_zifang",term:"田子方",pinyin:"tián zǐ fāng",meaning:"古代人物，传统记载与魏文侯有关。此处作为向文侯介绍其师的人物，不在本页强定其师承谱系。侍坐：陪坐在旁。"},{id:"tzf_teacher_xigong",term:"数称谿工",pinyin:"shuò chēng xī gōng",meaning:"多次称赞谿工。数读 shuò；谿工为人名。称道数当：其论说屡能切当，当在切合义读 dàng。"},{id:"tzf_teacher_wuze",term:"无择",pinyin:"wú zé",meaning:"田子方在篇中的自称。里人：同里之人、乡人。"},{id:"tzf_teacher_shunzi",term:"东郭顺子",pinyin:"dōng guō shùn zǐ",meaning:"篇中田子方的老师。其具体身世不详，按本段所描写的得道人物阅读，不直接断言已经考定为历史人物或纯粹虚构。"},{id:"tzf_teacher_tianxu",term:"人貌而天虚",pinyin:"rén mào ér tiān xū",meaning:"有人的形貌，而其精神虚静、自然。天虚可联系天然虚静理解，不必推成内心在空间上无限或完全没有任何想法。"},{id:"tzf_teacher_baozhen",term:"缘而葆真",pinyin:"yuán ér bǎo zhēn",meaning:"顺循事物、情势而保有真实。缘：顺循；葆：保。既不强作，也不因随顺而失去根本。"},{id:"tzf_teacher_rongwu",term:"清而容物",pinyin:"qīng ér róng wù",meaning:"清明而能容纳、应接事物。不因自持清明便排斥他物，也不等于无条件认可所有行为。"},{id:"tzf_teacher_zhengrong",term:"正容以悟之",pinyin:"zhèng róng yǐ wù zhī",meaning:"端正自身仪容，使对方有所醒悟。悟亦有联系寤、觉醒理解者。使人之意也消：使其某种偏执、意气消解，不是取消全部意志与思考。"},{id:"tzf_teacher_tangran",term:"傥然",pinyin:"tǎng rán",meaning:"若有所失、怅然的样子，具体训释有差异。下接终日不言，写文侯受到震动。"},{id:"tzf_teacher_quande",term:"全德之君子",pinyin:"quán dé zhī jūn zǐ",meaning:"德性、生命成就完整的君子。是文侯对所闻人物的赞叹，不在此建立严格的境界等级。"},{id:"tzf_teacher_tugeng",term:"土埂",pinyin:"tǔ gěng",meaning:"土堆、土梗等，字形与解释有差异，借喻所学浅陋。形解：形体松解；口钳：像被钳住而难言。"}],g=[{id:"tzf_meet_s1",label:"温伯雪子拒见：明乎礼义而陋于知人心",sentences:[[{text:"温伯雪子",glossary:"tzf_meet_wenbo"},"适齐，舍于鲁。鲁人有请见之者，温伯雪子曰：「不可。"],["吾闻",{text:"中国之君子",glossary:"tzf_meet_zhongguo"},"，明乎礼义而",{text:"陋于知人心",glossary:"tzf_meet_renxin"},"。吾不欲见也。」"]]},{id:"tzf_meet_s2",label:"往返鲁国：再次请见",sentences:[["至于齐，反舍于鲁，是人也又请见。"],["温伯雪子曰：「往也",{text:"蕲",glossary:"tzf_meet_qi"},"见我，今也又蕲见我，是必有以",{text:"振我",glossary:"tzf_meet_zhenwo"},"也。」"],["出而见客，入而叹。明日见客，又入而叹。"]]},{id:"tzf_meet_s3",label:"进退成规矩：其谏似子，其道似父",sentences:[["其仆曰：「每见之客也，必入而叹，何耶？」"],["曰：「吾固告子矣：中国之民，明乎礼义而陋乎知人心。"],["昔之见我者，",{text:"进退一成规、一成矩",glossary:"tzf_meet_guiju"},"，从容一若龙、一若虎。"],["其谏我也似子，其",{text:"道我",glossary:"tzf_meet_daowo"},"也似父，是以叹也。」"]]},{id:"tzf_meet_s4",label:"仲尼见而不言：目击而道存",sentences:[["仲尼见之而不言。子路曰：「吾子欲见温伯雪子久矣。见之而不言，何邪？」"],["仲尼曰：「若夫人者，",{text:"目击而道存",glossary:"tzf_meet_muji"},"矣，亦",{text:"不可以容声",glossary:"tzf_meet_rongsheng"},"矣！」"]]}],h=[{id:"tzf_meet_wenbo",term:"温伯雪子",pinyin:"wēn bó xuě zǐ",meaning:"篇中的论道人物，具体身世不详。适齐：往齐国；舍于鲁：在鲁国住宿，舍在住宿义读 shè。"},{id:"tzf_meet_zhongguo",term:"中国之君子",pinyin:"zhōng guó zhī jūn zǐ",meaning:"中原地区的君子。中国为古代地域用语，不直接等同现代国家名称；这里首先是温伯雪子的评价。"},{id:"tzf_meet_renxin",term:"陋于知人心",pinyin:"lòu yú zhī rén xīn",meaning:"在理解人心方面浅陋。与明乎礼义相对，检验规范熟练是否真正转成理解他人的能力。"},{id:"tzf_meet_qi",term:"蕲",pinyin:"qí",meaning:"求、请求。往也蕲见我：先前请求见我。反：返回。"},{id:"tzf_meet_zhenwo",term:"振我",pinyin:"zhèn wǒ",meaning:"振发、启发我，亦有其他训释。温伯雪子由拒见转为期待受益，不宜只按震慑解。"},{id:"tzf_meet_guiju",term:"进退一成规、一成矩",pinyin:"jìn tuì yī chéng guī, yī chéng jǔ",meaning:"进退举动如合规矩，仪节整齐。规、矩本为作圆、作方之具。不直接证明对方蓄意欺骗。"},{id:"tzf_meet_daowo",term:"道我",pinyin:"dǎo wǒ",meaning:"引导我，道联系导理解。其谏似子、其道似父：交往被置于子父角色般的规劝、指导关系中。"},{id:"tzf_meet_muji",term:"目击而道存",pinyin:"mù jī ér dào cún",meaning:"目相接、相见之际，道已呈现或心领相契。击联系相接理解，不只是看见外貌便自动知道一切。"},{id:"tzf_meet_rongsheng",term:"不可以容声",pinyin:"bù kě yǐ róng shēng",meaning:"此际不宜再加入言声，或不是言声所能充分表达。不能据此推成一切语言都无价值。"}],m=[{id:"tzf_follow_s1",label:"颜渊之问：步、趋、驰与奔逸绝尘",sentences:[["颜渊问于仲尼曰：「夫子步亦步，夫子趋亦趋，夫子驰亦驰，夫子",{text:"奔逸绝尘",glossary:"tzf_follow_benyi"},"，而回",{text:"瞠若乎后",glossary:"tzf_follow_cheng"},"矣！」"],["夫子曰：「回，何谓邪？」"]]},{id:"tzf_follow_s2",label:"能随言辩，不能随不言而信",sentences:[["曰：「夫子步亦步也，夫子言亦言也；夫子趋亦趋也，夫子辩亦辩也；夫子驰亦驰也，夫子言道，回亦言道也；"],["及奔逸绝尘而回瞠若乎后者，夫子",{text:"不言而信",glossary:"tzf_follow_xin"},"，",{text:"不比而周",glossary:"tzf_follow_bizhou"},"，",{text:"无器而民滔乎前",glossary:"tzf_follow_wuqi"},"，而不知所以然而已矣。」"]]},{id:"tzf_follow_s3",label:"哀莫大于心死：万物有待",sentences:[["仲尼曰：「恶！可不察与！夫",{text:"哀莫大于心死",glossary:"tzf_follow_xinsi"},"，而人死亦次之。"],["日出东方而入于西极，万物莫不",{text:"比方",glossary:"tzf_follow_bifang"},"，有目有趾者，待是而后成功。"],["是出则存，是入则亡。万物亦然，有待也而死，有待也而生。"]]},{id:"tzf_follow_s4",label:"成形与日徂：生命不断迁移",sentences:[["吾一受其成形，而",{text:"不化以待尽",glossary:"tzf_follow_buhua"},"。效物而动，日夜无隙，而不知其所终。"],[{text:"薰然其成形",glossary:"tzf_follow_xunran"},"，知命不能规乎其前。丘以是日",{text:"徂",glossary:"tzf_follow_cu"},"。"]]},{id:"tzf_follow_s5",label:"交臂而失：不要追逐已经过去的老师",sentences:[["吾终身与汝",{text:"交一臂而失之",glossary:"tzf_follow_jiaobi"},"，可不哀与？"],["女殆",{text:"著乎吾所以著",glossary:"tzf_follow_zhu"},"也。彼已尽矣，而女求之以为有，是",{text:"求马于唐肆",glossary:"tzf_follow_tangsi"},"也。"],["吾服，女也甚忘；女服，吾也甚忘。"]]},{id:"tzf_follow_s6",label:"虽忘乎故吾：吾有不忘者存",sentences:[["虽然，女奚患焉！虽忘乎",{text:"故吾",glossary:"tzf_follow_guwu"},"，吾有",{text:"不忘者存",glossary:"tzf_follow_buwang"},"。」"]]}],_=[{id:"tzf_follow_benyi",term:"奔逸绝尘",pinyin:"bēn yì jué chén",meaning:"疾驰而远，尘迹也难以追及。是颜渊描述无法跟随的譬喻，不是实际比赛速度。趋：快步；驰：疾行。"},{id:"tzf_follow_cheng",term:"瞠若乎后",pinyin:"chēng ruò hū hòu",meaning:"睁目而留在后面，形容追随不及、惊望的状态。"},{id:"tzf_follow_xin",term:"不言而信",pinyin:"bù yán ér xìn",meaning:"不凭言说而仍能使人相信、信任。不能据此认为沉默者一定可信。"},{id:"tzf_follow_bizhou",term:"不比而周",pinyin:"bù bǐ ér zhōu",meaning:"不刻意亲附、结比，却能周遍相合。比联系亲比、结附理解；周联系周遍、周合理解。"},{id:"tzf_follow_wuqi",term:"无器而民滔乎前",pinyin:"wú qì ér mín tāo hū qián",meaning:"不凭某种显设的器用、权势或手段，而人众涌集于前。器与滔的具体训释有空间，不等于没有任何行为和条件。"},{id:"tzf_follow_xinsi",term:"哀莫大于心死",pinyin:"āi mò dà yú xīn sǐ",meaning:"最大的悲哀在心的死滞。结合追执故吾，可联系心失去随化、应接的活力理解；不是临床诊断，也不宜简单归成情绪低落或不再追求成功。"},{id:"tzf_follow_bifang",term:"比方",pinyin:"bǐ fāng",meaning:"依循、相应或各有所向等，有不同解释。此处不是举例比喻的现代用语。日出、日入的存亡描写，不直接等于每到夜晚万物全部死亡。"},{id:"tzf_follow_buhua",term:"不化以待尽",pinyin:"bù huà yǐ dài jìn",meaning:"疑难句，可联系既受成形、形体终将耗尽理解。与下文效物而动、日徂连读，不宜据此断言孔子主张拒绝一切变化。"},{id:"tzf_follow_xunran",term:"薰然其成形",pinyin:"xūn rán qí chéng xíng",meaning:"薰然有和顺、蒸变等解释，整句涉及形体生成与变化。知命不能规乎其前：不能预先完全规度生命遭际。"},{id:"tzf_follow_cu",term:"徂",pinyin:"cú",meaning:"往、逝。丘以是日徂：孔丘也随此一天天迁往、流逝。"},{id:"tzf_follow_jiaobi",term:"交一臂而失之",pinyin:"jiāo yī bì ér shī zhī",meaning:"交臂之间便已错过，写变化迅速、相交者也不保持原样。一臂不必强定为计时单位。"},{id:"tzf_follow_zhu",term:"著乎吾所以著",pinyin:"zhuó hū wú suǒ yǐ zhù",meaning:"著有执著、显著等不同用法。可理解为你执著于我已经显露的样子、言行；不直接译成你执著于我所执著的东西。女通汝。"},{id:"tzf_follow_tangsi",term:"求马于唐肆",pinyin:"qiú mǎ yú táng sì",meaning:"到不宜求马的肆场求马，喻向错误的所在索求。唐肆有空肆、道路等训释，不强定为已经关闭的马市场。"},{id:"tzf_follow_guwu",term:"故吾",pinyin:"gù wú",meaning:"过去的我、旧有的样貌与表现。吾服、女服为疑难语句，常联系所服习、服行之事理解，不直接按互相佩服翻译。"},{id:"tzf_follow_buwang",term:"不忘者存",pinyin:"bù wàng zhě cún",meaning:"仍有不忘、未失者存在。可联系不被旧迹穷尽的根本、真实相通或持续应化理解；具体所指有争议，不直接作为个人灵魂永存的证明。"}],u=[{id:"tzf_lao_s1",label:"老聃新沐：似遗物离人而立于独",sentences:[["孔子见老聃，老聃新沐，方将",{text:"被发而干",glossary:"tzf_lao_pifa"},"，蛰然似非人。孔子便而待之。"],["少焉见，曰：「丘也眩与？其信然与？向者先生形体",{text:"掘若槁木",glossary:"tzf_lao_ju"},"，似遗物离人而",{text:"立于独",glossary:"tzf_lao_du"},"也。」"]]},{id:"tzf_lao_s2",label:"吾游心于物之初：议乎其将",sentences:[["老聃曰：「吾游心于",{text:"物之初",glossary:"tzf_lao_wuchu"},"。」孔子曰：「何谓邪？」"],["曰：「心困焉而不能知，口辟焉而不能言。尝为汝",{text:"议乎其将",glossary:"tzf_lao_qijiang"},"："]]},{id:"tzf_lao_s3",label:"阴阳交通：万物生焉",sentences:[["至阴肃肃，至阳赫赫。肃肃出乎天，赫赫发乎地。两者交通成和而物生焉，或为之纪而莫见其形。"],[{text:"消息满虚",glossary:"tzf_lao_xiaoxi"},"，一晦一明，日改月化，日有所为而莫见其功。"],["生有所乎萌，死有所乎归，始终相反乎无端，而莫知乎其所穷。非是也，且孰为之宗！」"]]},{id:"tzf_lao_s4",label:"得至美而游乎至乐：谓之至人",sentences:[["孔子曰：「请问游是。」"],["老聃曰：「夫得是至美至乐也。得至美而游乎至乐，谓之至人。」"],["孔子曰：「愿闻其方。」"]]},{id:"tzf_lao_s5",label:"行小变而不失其大常",sentences:[["曰：「草食之兽，不疾易薮；水生之虫，不疾易水。行小变而不失其",{text:"大常",glossary:"tzf_lao_dachang"},"也，喜怒哀乐不入于胸次。"],["夫天下也者，万物之所一也。得其所一而同焉，则四支百体将为尘垢，而死生终始将为昼夜，而莫之能",{text:"滑",glossary:"tzf_lao_gu"},"，而况得丧祸福之所介乎！"]]},{id:"tzf_lao_s6",label:"贵在于我而不失于变",sentences:[["弃",{text:"隶",glossary:"tzf_lao_li"},"者若弃泥涂，知身贵于隶也。贵在于我而不失于变。"],["且万化而未始有极也，夫孰足以患心！已为道者解乎此。」"]]},{id:"tzf_lao_s7",label:"何修焉：如天高地厚、日月自明",sentences:[["孔子曰：「夫子德配天地，而犹假至言以修心。古之君子，孰能脱焉！」"],["老聃曰：「不然。夫水之于",{text:"汋",glossary:"tzf_lao_zhuo"},"也，无为而才自然矣；至人之于德也，不修而物不能离焉。"],["若天之自高，地之自厚，日月之自明，夫何修焉！」"]]},{id:"tzf_lao_s8",label:"孔子自比醯鸡：发吾覆",sentences:[["孔子出，以告颜回曰：「丘之于道也，其犹",{text:"醯鸡",glossary:"tzf_lao_xiji"},"与！"],["微夫子之",{text:"发吾覆",glossary:"tzf_lao_fafu"},"也，吾不知天地之大全也。」"]]}],f=[{id:"tzf_lao_pifa",term:"被发而干",pinyin:"pī fà ér gān",meaning:"披散头发使其晾干。被通披；新沐：刚洗头；蛰然：静止的样子。孔子便而待之，常联系退避、稍让而等待理解。"},{id:"tzf_lao_ju",term:"掘若槁木",pinyin:"jué ruò gǎo mù",meaning:"僵然、静止如枯木。掘有异文与不同读法，此处保留来稿，不按挖掘之义解释。"},{id:"tzf_lao_du",term:"立于独",pinyin:"lì yú dú",meaning:"处于不受外物拘牵、独立通达的状态。不必解释为身体实际站进虚空，也不是彻底拒绝与人往来。"},{id:"tzf_lao_wuchu",term:"物之初",pinyin:"wù zhī chū",meaning:"万物生成的根本、初始。可联系道与造化理解，不直接等同现代宇宙学某个已确定时刻。"},{id:"tzf_lao_qijiang",term:"议乎其将",pinyin:"yì hū qí jiāng",meaning:"尝试论说其大概、近似面貌。将的具体训释有空间，整体保留言说不能尽其所述的限度。"},{id:"tzf_lao_xiaoxi",term:"消息满虚",pinyin:"xiāo xī mǎn xū",meaning:"消减、生长、充满、虚缺。消息不是现代信息义，与晦明、日改月化共同描述变化。"},{id:"tzf_lao_dachang",term:"大常",pinyin:"dà cháng",meaning:"根本的常道、生命所循的基本条件。不疾易薮、不疾易水常可联系不以更换生活之地为患理解，不只译成不急着换地方。"},{id:"tzf_lao_gu",term:"滑",pinyin:"gǔ",meaning:"扰乱。喜怒哀乐不入胸次与莫之能滑，可联系不被变化、情绪执持所扰，不必理解成彻底没有感情。"},{id:"tzf_lao_li",term:"隶",pinyin:"lì",meaning:"仆隶、所附属者等；亦有联系爵禄地位的解释。弃隶者若弃泥涂的具体所指有争议，不将隶直接等同爵位。"},{id:"tzf_lao_zhuo",term:"汋",pinyin:"zhuó",meaning:"水的流动、激动或涌出等，具体训释有差异。譬喻突出水的作用自然发生，不依刻意加工。"},{id:"tzf_lao_xiji",term:"醯鸡",pinyin:"xī jī",meaning:"醋瓮中滋生的小虫。醯：醋；鸡在此非家鸡。借受容器遮限的小虫比喻见识受限。"},{id:"tzf_lao_fafu",term:"发吾覆",pinyin:"fā wú fù",meaning:"揭开遮住我的覆盖物。微：若非；天地之大全：天地的广大、完整，不等于已经穷尽全部宇宙知识。"}],b=[{id:"tzf_robe_s1",label:"鲁多儒士，还是鲁少儒",sentences:[["庄子见鲁哀公，哀公曰：「鲁多儒士，少为先生",{text:"方",glossary:"tzf_robe_fang"},"者。」"],["庄子曰：「鲁少儒。」"],["哀公曰：「举鲁国而儒服，何谓少乎？」"]]},{id:"tzf_robe_s2",label:"圜冠、句履、佩玦：服饰与所知",sentences:[["庄子曰：「周闻之：儒者冠",{text:"圜冠",glossary:"tzf_robe_yuanguan"},"者知天时，履",{text:"句履",glossary:"tzf_robe_julv"},"者知地形，缓佩",{text:"玦",glossary:"tzf_robe_jue"},"者事至而断。"],["君子有其道者，未必为其服也；为其服者，未必知其道也。"]]},{id:"tzf_robe_s3",label:"号于国中：以极端命令检验儒服",sentences:[["公固以为不然，何不",{text:"号于国中",glossary:"tzf_robe_hao"},"曰：『无此道而为此服者，其罪死！』」"],["于是哀公号之五日，而鲁国无敢儒服者。"]]},{id:"tzf_robe_s4",label:"独一丈夫：问以国事而不穷",sentences:[["独有一丈夫，儒服而立乎公门。公即召而问以国事，千转万变而不穷。"],["庄子曰：「以鲁国而儒者一人耳，可谓多乎？」"]]}],y=[{id:"tzf_robe_fang",term:"方",pinyin:"fāng",meaning:"方术、学说或道路。少为先生方者：从事、奉行先生之道的人少。鲁哀公与庄子时代不合，本段有寓言性的时代错置。"},{id:"tzf_robe_yuanguan",term:"圜冠",pinyin:"yuán guān",meaning:"圆形帽。冠圜冠的前一冠作戴帽动词，读 guàn，后一冠作名词，读 guān。"},{id:"tzf_robe_julv",term:"句履",pinyin:"jù lǚ",meaning:"鞋名，常释为方形鞋头，具体形制有讨论空间。句有不同音读处理，宜依所用注本统一。"},{id:"tzf_robe_jue",term:"玦",pinyin:"jué",meaning:"有缺口的环形玉器。文中借玦与决断关联；缓佩玦的缓亦有字义、异文讨论，不将所有佩玉一概解释成善断。"},{id:"tzf_robe_hao",term:"号于国中",pinyin:"hào yú guó zhōng",meaning:"在国中发布号令。其罪死为故事中的严酷设令，不是本页认可的现实惩罚原则。"}],c=[{id:"tzf_free_s1",label:"百里奚：爵禄不入于心",sentences:[[{text:"百里奚",glossary:"tzf_free_bailixi"},"爵禄不入于心，故",{text:"饭牛",glossary:"tzf_free_fanniu"},"而牛肥，使秦穆公忘其贱，",{text:"与之政",glossary:"tzf_free_yuzheng"},"也。"]]},{id:"tzf_free_s2",label:"有虞氏：死生不入于心",sentences:[[{text:"有虞氏",glossary:"tzf_free_yuyushi"},"死生不入于心，故足以动人。"]]}],z=[{id:"tzf_free_bailixi",term:"百里奚",pinyin:"bǎi lǐ xī",meaning:"传统记载中的秦穆公贤臣，身世有不同叙述。此处突出其不以爵禄占据心神，不据两句话复原完整历史。"},{id:"tzf_free_fanniu",term:"饭牛",pinyin:"fàn niú",meaning:"给牛喂食、养牛。饭在此作动词，不是牛吃人类米饭的意思。"},{id:"tzf_free_yuzheng",term:"与之政",pinyin:"yǔ zhī zhèng",meaning:"授予他政事、让他参与治理。忘其贱：不以原先卑下身份限制对他的评价。"},{id:"tzf_free_yuyushi",term:"有虞氏",pinyin:"yǒu yú shì",meaning:"舜的称号。死生不入于心：不以死生之虑拘系心神，不是无视生命或没有感受。动人：使人受到感发。"}],x=[{id:"tzf_paint_s1",label:"众史皆至：受揖而立，舐笔和墨",sentences:[["宋元君将画图，众",{text:"史",glossary:"tzf_paint_shi"},"皆至，",{text:"受揖而立",glossary:"tzf_paint_shouyi"},"，",{text:"舐笔和墨",glossary:"tzf_paint_shibi"},"，在外者半。"]]},{id:"tzf_paint_s2",label:"一史后至：儃儃然不趋",sentences:[["有一史后至者，",{text:"儃儃然不趋",glossary:"tzf_paint_tantan"},"，受揖不立，因之舍。"],["公使人视之，则",{text:"解衣般礴裸",glossary:"tzf_paint_panbo"},"。"]]},{id:"tzf_paint_s3",label:"宋元君之判断：是真画者",sentences:[["君曰：「可矣，是真画者也。」"]]}],q=[{id:"tzf_paint_shi",term:"史",pinyin:"shǐ",meaning:"此处指画史、画师，不作现代历史学者解。宋元君将画图：召人绘图，具体图画用途不详。"},{id:"tzf_paint_shouyi",term:"受揖而立",pinyin:"shòu yī ér lì",meaning:"受召、受礼或受命后站立，具体训释有差异。揖读 yī；不必只理解为君主向每位画师作揖。"},{id:"tzf_paint_shibi",term:"舐笔和墨",pinyin:"shì bǐ hé mò",meaning:"舐笔、调和墨汁，准备作画。舐：舔；和：调和。在外者半：仍有许多画师在外等候。"},{id:"tzf_paint_tantan",term:"儃儃然不趋",pinyin:"tǎn tǎn rán bù qū",meaning:"从容舒缓，不急步趋进。儃有不同音读，此处按从容舒缓义读 tǎn；因之舍：随后往舍处，不必补写为故意拒绝任务。"},{id:"tzf_paint_panbo",term:"解衣般礴裸",pinyin:"jiě yī pán bó luǒ",meaning:"解衣、舒展或箕踞而坐，身体裸露。般礴亦写作盘礴等，具体坐姿有不同解释；重点在不拘束的状态，不是要求现实创作必须裸体。"}],k=[{id:"tzf_zang_s1",label:"文王观于臧：其钓莫钓，常钓也",sentences:[["文王观于臧，见一丈夫钓，而",{text:"其钓莫钓",glossary:"tzf_zang_changdiao"},"。非持其钓有钓者也，常钓也。"]]},{id:"tzf_zang_s2",label:"文王两难：欲授之政，又恐大臣不安",sentences:[["文王欲举而授之政，而恐大臣父兄之弗安也；欲终而释之，而不忍百姓之无天也。"],["于是旦而",{text:"属之大夫",glossary:"tzf_zang_zhudaifu"},"曰：「昔者寡人梦见良人，黑色而髯，乘驳马而偏朱蹄，号曰："],["『",{text:"寓而政于臧丈人",glossary:"tzf_zang_yuzheng"},"，庶几乎民有",{text:"瘳",glossary:"tzf_zang_chou"},"乎！』」"]]},{id:"tzf_zang_s3",label:"先君之命：迎臧丈人而授政",sentences:[["诸大夫蹴然曰：「先君王也。」文王曰：「然则卜之。」"],["诸大夫曰：「先君之命，王其无它，又何卜焉。」遂迎臧丈人而授之政。"]]},{id:"tzf_zang_s4",label:"三年观国：典法无更，偏令无出",sentences:[["典法无更，偏令无出。三年，文王观于国，则",{text:"列士坏植散群",glossary:"tzf_zang_huaizhi"},"，",{text:"长官者不成德",glossary:"tzf_zang_chengde"},"，",{text:"斔斛不敢入于四竟",glossary:"tzf_zang_yuhu"},"。"],["列士坏植散群，则尚同也；长官者不成德，则同务也；斔斛不敢入于四竟，则诸侯无二心也。"]]},{id:"tzf_zang_s5",label:"政可以及天下乎：臧丈人辞去",sentences:[["文王于是焉以为大师，",{text:"北面而问",glossary:"tzf_zang_beimian"},"曰：「政可以及天下乎？」"],["臧丈人昧然而不应，泛然而辞，",{text:"朝令而夜循",glossary:"tzf_zang_yexun"},"，终身无闻。"]]},{id:"tzf_zang_s6",label:"颜渊问梦：文王尽之，循斯须",sentences:[["颜渊问于仲尼曰：「文王其犹未邪？又何以梦为乎？」"],["仲尼曰：「默，汝无言！夫文王尽之也，而又何",{text:"论剌",glossary:"tzf_zang_lunci"},"焉！彼直以",{text:"循斯须",glossary:"tzf_zang_sixu"},"也。」"]]}],P=[{id:"tzf_zang_changdiao",term:"其钓莫钓，常钓也",pinyin:"qí diào mò diào, cháng diào yě",meaning:"疑难句，常联系钓而不以求鱼、求得为意，或无所特为的钓理解。不直接证明他没有任何目的，更不能据此确认其历史身份为姜太公。臧为篇中地名。"},{id:"tzf_zang_zhudaifu",term:"属之大夫",pinyin:"zhǔ zhī dà fū",meaning:"向大夫告语、嘱告。属读 zhǔ；旦：早晨；髯：胡须；驳马：杂色马。"},{id:"tzf_zang_yuzheng",term:"寓而政于臧丈人",pinyin:"yù rǔ zhèng yú zāng zhàng rén",meaning:"把你的政事寄托于臧地的丈人。寓：寄托；而在这里联系汝、你理解。丈人：年长男子、长者。"},{id:"tzf_zang_chou",term:"瘳",pinyin:"chōu",meaning:"病愈、好转。民有瘳借病愈说明民生困弊获得改善。庶几：或许、希望能够。"},{id:"tzf_zang_huaizhi",term:"列士坏植散群",pinyin:"liè shì huài zhí sàn qún",meaning:"列士消除自立的藩篱、离散私群等，具体训释有差异。植联系立、树立理解，不强定为拆除军事营垒；下文以尚同说明其效果。"},{id:"tzf_zang_chengde",term:"长官者不成德",pinyin:"zhǎng guān zhě bù chéng dé",meaning:"居长官者不将功德据为己有、独成其德等，有不同解释。与同务相接，不作官员没有德行解。"},{id:"tzf_zang_yuhu",term:"斔斛不敢入于四竟",pinyin:"yǔ hú bù gǎn rù yú sì jìng",meaning:"斔斛为量器，句意有量制一致、输纳与侵扰等不同解释，不直接定为贿赂绝迹。竟通境；下文以诸侯无二心解释其政治意义。"},{id:"tzf_zang_beimian",term:"北面而问",pinyin:"běi miàn ér wèn",meaning:"面北请教，表示尊其为师。大师常联系太师理解。这里可说明师礼，不必将文王身份直接改成臣子。"},{id:"tzf_zang_yexun",term:"朝令而夜循",pinyin:"zhāo lìng ér yè xún",meaning:"疑难句，循常联系遁去理解，亦有读音与字形讨论。结合泛然而辞，写其辞去、隐退；不按晚上遵守命令简单翻译。"},{id:"tzf_zang_lunci",term:"论剌",pinyin:"lùn cì",meaning:"论议、讥刺。剌在此常联系刺理解，具体字形宜据底本统一。"},{id:"tzf_zang_sixu",term:"循斯须",pinyin:"xún sī xū",meaning:"顺循一时情势、片刻条件等。彼所指有不同理解，可联系文王因时应变，也有联系臧丈人者；不把代词指向强定为唯一解释。"}],w=[{id:"tzf_arch_s1",label:"列御寇射：肘上杯水，犹象人",sentences:[["列御寇为伯昏无人射，",{text:"引之盈贯",glossary:"tzf_arch_yingguan"},"，措杯水其肘上，发之，",{text:"适矢复沓，方矢复寓",glossary:"tzf_arch_futa"},"。"],["当是时，犹",{text:"象人",glossary:"tzf_arch_xiangren"},"也。"]]},{id:"tzf_arch_s2",label:"射之射与不射之射：临渊能射乎",sentences:[["伯昏无人曰：「是",{text:"射之射，非不射之射",glossary:"tzf_arch_bush e"},"也。"],["尝与汝登高山，履危石，临百仞之渊，若能射乎？」"]]},{id:"tzf_arch_s3",label:"伯昏临渊，御寇伏地",sentences:[["于是无人遂登高山，履危石，临百仞之渊，",{text:"背逡巡",glossary:"tzf_arch_qunxun"},"，足二分垂在外，揖御寇而进之。"],["御寇伏地，汗流至踵。"]]},{id:"tzf_arch_s4",label:"至人神气不变：于中也殆",sentences:[["伯昏无人曰：「夫至人者，上窥青天，下潜黄泉，",{text:"挥斥八极",glossary:"tzf_arch_huichi"},"，神气不变。"],["今汝怵然有",{text:"恂目之志",glossary:"tzf_arch_xunmu"},"，尔于",{text:"中",glossary:"tzf_arch_zhong"},"也殆矣夫！」"]]}],T=[{id:"tzf_arch_yingguan",term:"引之盈贯",pinyin:"yǐn zhī yíng guàn",meaning:"拉弓至满。列御寇即列子，伯昏无人为篇中指导他的人物。措：置、放；为伯昏无人射：射给他看。"},{id:"tzf_arch_futa",term:"适矢复沓，方矢复寓",pinyin:"shì shǐ fù tà, fāng shǐ fù yù",meaning:"射出的箭与接续搭上的箭连续相继，具体词义有差异。重点在发射接续而动作稳定，不强定每个词对应第几支箭。"},{id:"tzf_arch_xiangren",term:"象人",pinyin:"xiàng rén",meaning:"偶人、刻成的人像。形容稳定如木偶，不等于他毫无意识，也不证明整个身体绝对不动。"},{id:"tzf_arch_bush e",term:"射之射，非不射之射",pinyin:"shè zhī shè, fēi bù shè zhī shè",meaning:"以射为意的射，与不受射之意拘系的射相区分。可联系技艺与精神状态理解，不直接译成有意识与无意识，也不等于拒绝训练。"},{id:"tzf_arch_qunxun",term:"背逡巡",pinyin:"bèi qūn xún",meaning:"背向深渊而缓缓退近。足二分垂在外通常联系脚的大部分悬出理解，不把古文比例当成可复刻的安全操作。"},{id:"tzf_arch_huichi",term:"挥斥八极",pinyin:"huī chì bā jí",meaning:"精神奔放、游行于八方极远之处。上下青天黄泉是夸张的精神意象，不按肉身可以自由进入极端环境解释。"},{id:"tzf_arch_xunmu",term:"恂目之志",pinyin:"xún mù zhī zhì",meaning:"惊惧、目光失稳的状态等，恂有训释讨论。怵然：恐惧的样子；踵：脚后跟。"},{id:"tzf_arch_zhong",term:"中",pinyin:"zhòng / zhōng",meaning:"有命中目标与内在状态等不同解释。若按射中读 zhòng，若按内中读 zhōng；结合射箭与心神受扰，可说明其命中已不可靠，不强定为内心危险。"}],j=[{id:"tzf_sun_s1",label:"三为三去：鼻间栩栩然",sentences:[["肩吾问于孙叔敖曰：「子三为",{text:"令尹",glossary:"tzf_sun_lingyin"},"而不荣华，三去之而无忧色。"],["吾始也疑子，今视子之鼻间",{text:"栩栩然",glossary:"tzf_sun_xuxu"},"，子之用心独奈何？」"]]},{id:"tzf_sun_s2",label:"来不可却，去不可止：得失之非我",sentences:[["孙叔敖曰：「吾何以过人哉！吾以其来不可却也，其去不可止也。"],["吾以为",{text:"得失之非我",glossary:"tzf_sun_de shi"},"也，而无忧色而已矣。我何以过人哉！"]]},{id:"tzf_sun_s3",label:"彼与我：何暇人贵人贱",sentences:[["且不知其在彼乎？其在我乎？其在彼邪",{text:"亡乎我",glossary:"tzf_sun_wu"},"，在我邪亡乎彼。"],["方将踌躇，方将四顾，何暇至乎人贵人贱哉！」"]]},{id:"tzf_sun_s4",label:"仲尼论真人：死生无变，况爵禄",sentences:[["仲尼闻之曰：「古之真人，",{text:"知者不得说",glossary:"tzf_sun_shui"},"，美人不得滥，盗人不得劫，",{text:"伏戏、黄帝不得友",glossary:"tzf_sun_fuxi"},"。"],["死生亦大矣，而无变乎己，况爵禄乎！"]]},{id:"tzf_sun_s5",label:"神经大山：既以与人己愈有",sentences:[["若然者，其神经乎大山而无介，入乎渊泉而不",{text:"濡",glossary:"tzf_sun_ru"},"，处卑细而不惫，充满天地，",{text:"既以与人己愈有",glossary:"tzf_sun_yuren"},"。」"]]}],S=[{id:"tzf_sun_lingyin",term:"令尹",pinyin:"lìng yǐn",meaning:"楚国重要执政官名。孙叔敖为古代记载中的楚国贤臣，三为三去按本篇叙述阅读，不据此精确复原任职年表。"},{id:"tzf_sun_xuxu",term:"栩栩然",pinyin:"xǔ xǔ rán",meaning:"舒畅自得的样子。鼻间可联系呼吸气息理解，不是用生理测量证明已经没有情绪。"},{id:"tzf_sun_de shi",term:"得失之非我",pinyin:"dé shī zhī fēi wǒ",meaning:"职位得失不能全由自己决定，也不构成全部的自己。非我可联系不在己、不属于己的固有成就理解，不直接推成有一个完全不变的实体自我。"},{id:"tzf_sun_wu",term:"亡乎我",pinyin:"wú hū wǒ",meaning:"在我这里没有。亡通无，读 wú。其所指及彼我关系有训释空间，常联系贵的所在、职位与自身的关系考察。"},{id:"tzf_sun_shui",term:"知者不得说",pinyin:"zhì zhě bù dé shuì",meaning:"智者不能凭辩说使其转移根本。说按劝说义读 shuì；不意味着真人拒绝所有理由与修正。滥联系侵乱、迷乱理解。"},{id:"tzf_sun_fuxi",term:"伏戏、黄帝不得友",pinyin:"fú xī, huáng dì bù dé yǒu",meaning:"伏戏即伏羲的异写。不得友是夸张的境界描述，具体解释有差异，不直接定为真人在历史排名上高于二帝或不能与人交友。"},{id:"tzf_sun_ru",term:"濡",pinyin:"rú",meaning:"沾湿。神经大山、入渊不濡等写精神不受阻染的理想，不是肉身防水、穿山或免伤承诺。介：阻碍、间隔等。"},{id:"tzf_sun_yuren",term:"既以与人己愈有",pinyin:"jì yǐ yǔ rén jǐ yù yǒu",meaning:"给予他人，自身反而更充实。可联系德行、关怀与生命成就理解，不作金钱、时间等有限资源越给越多的算术保证。"}],A=[{id:"tzf_fan_s1",label:"楚王左右三言凡亡",sentences:[["楚王与",{text:"凡君",glossary:"tzf_fan_fanjun"},"坐，少焉，楚王左右曰「凡亡」者三。"]]},{id:"tzf_fan_s2",label:"凡之亡不足以丧吾存",sentences:[["凡君曰：「凡之亡也，不足以",{text:"丧吾存",glossary:"tzf_fan_sangcun"},"。"],["夫凡之亡不足以丧吾存，则楚之存不足以",{text:"存存",glossary:"tzf_fan_cuncun"},"。"]]},{id:"tzf_fan_s3",label:"凡未始亡而楚未始存",sentences:[["由是观之，则",{text:"凡未始亡而楚未始存",glossary:"tzf_fan_weishi"},"也。」"]]}],C=[{id:"tzf_fan_fanjun",term:"凡君",pinyin:"fán jūn",meaning:"凡国之君，具体历史身份不在此坐实。左右：侍从；少焉：不久。三言凡亡形成反复强调的叙事效果。"},{id:"tzf_fan_sangcun",term:"丧吾存",pinyin:"sàng wú cún",meaning:"使我的存有、生命安顿丧失。吾存所指有解释空间，可联系不被国位穷尽的自身理解，不直接推成灵魂不灭。"},{id:"tzf_fan_cuncun",term:"存存",pinyin:"cún cún",meaning:"使所存者得以存、保全真正所存等。前一存可作动词，后一存联系所存理解；不宜译成毫无解释力的存在使存在存在。"},{id:"tzf_fan_weishi",term:"凡未始亡而楚未始存",pinyin:"fán wèi shǐ wáng ér chǔ wèi shǐ cún",meaning:"在前文转换后的尺度上，凡之亡不尽其所存，楚之存也不足保证其所存。未始：未曾。不是取消历史中的国土、制度与人民损失。"}];return(v,t)=>{const V=l("DaoReadingPrelude"),s=l("DaoTextReading"),r=l("DaoKeywordCards"),d=l("DaoLineGuide");return D(),R("div",null,[t[0]||(t[0]=i('<h1 id="庄子·田子方" tabindex="-1">庄子·田子方 <a class="header-anchor" href="#庄子·田子方" aria-label="Permalink to &quot;庄子·田子方&quot;">​</a></h1><h2 id="篇名释义" tabindex="-1">篇名释义 <a class="header-anchor" href="#篇名释义" aria-label="Permalink to &quot;篇名释义&quot;">​</a></h2><blockquote><p><strong>田子方</strong></p><p>篇名取自开头的人物田子方，不意味着全篇都是他的生平或学说。</p><p>开篇借他与魏文侯的对话，区分两种可敬之处：</p><p><strong>论说屡能切当。</strong></p><p><strong>为人真实，能顺循而葆真、清明而容物。</strong></p></blockquote><p>谿工因「称道数当」而被称赞，东郭顺子却使田子方说：</p><blockquote><p><strong>无择何足以称之！</strong></p></blockquote><p>这一反差，不必解释成所有语言都无效，而是引出一个持续的问题：</p><p><strong>一个人的成就，是否能够只凭说了什么、穿了什么、表现得多合规矩来判断？</strong></p><p>前六段不断把阅读从可见的标志，推进到：</p><ul><li>言行是否与真实相通。</li><li>熟悉礼义是否也能理解人心。</li><li>追随老师是否只是在复制旧迹。</li><li>面对变化是否仍能保持根本。</li><li>名位与外在所得是否占据心神。</li></ul>',9)),a(V,{title:"先读前六段：从称道切当，到真实成就与不以名位立己",summary:"田子方介绍东郭顺子，开启对真实与全德的追问；温伯雪子区分礼仪熟练与知人心；颜渊与孔子的对话检验追随旧迹的限度；孔子见老聃转向物之初与自然之德；儒服故事和百里奚短章，则把问题放回身份、能力与具体行动。",points:[{label:"先看",text:"缘而葆真、清而容物，为什么要把顺应与保持根本连在一起？"},{label:"再问",text:"目击而道存、不言而信，是否意味着言语与学习都应取消？"},{label:"最后",text:"有其服未必有其道；不以爵禄为念，又怎样仍能认真做事？"}],hint:"全篇十一段均已整理：前六段立起「真实成就不止于可见标志」的问题，后五段再落到技艺、权位、得失与存亡；文末的脉络逻辑链、三问解读、现代启发与关键词索引均覆盖全篇。"}),t[1]||(t[1]=n("h2",{id:"一、田子方侍坐·东郭顺子与全德之君子",tabindex:"-1"},[e("一、田子方侍坐·东郭顺子与全德之君子 "),n("a",{class:"header-anchor",href:"#一、田子方侍坐·东郭顺子与全德之君子","aria-label":'Permalink to "一、田子方侍坐·东郭顺子与全德之君子"'},"​")],-1)),t[2]||(t[2]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:o,glossary:p,"default-mode":"classic","aria-label":"田子方·田子方与魏文侯 原文"}),t[3]||(t[3]=n("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"侍坐",pinyin:["shì","zuò"],meaning:"陪坐在旁。"},{term:"数称谿工",pinyin:["shuò","chēng","xī","gōng"],meaning:"多次称赞谿工。数读 shuò。"},{term:"无择",pinyin:["wú","zé"],meaning:"田子方在篇中的自称。"},{term:"称道数当",pinyin:["chēng","dào","shuò","dàng"],meaning:"论说屡能切当。"},{term:"人貌而天虚",pinyin:["rén","mào","ér","tiān","xū"],meaning:"形貌是人，精神虚静自然。"},{term:"缘而葆真",pinyin:["yuán","ér","bǎo","zhēn"],meaning:"顺循事物，却不失真实。"},{term:"清而容物",pinyin:["qīng","ér","róng","wù"],meaning:"清明而能容纳、应接事物。"},{term:"正容",pinyin:["zhèng","róng"],meaning:"端正自身仪容。"},{term:"傥然",pinyin:["tǎng","rán"],meaning:"怅然、若有所失的样子。"},{term:"形解口钳",pinyin:["xíng","jiě","kǒu","qián"],meaning:"形体松解，口似被钳住，写受震动后的状态。"}]}),t[4]||(t[4]=n("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"不仅看论说是否切当，也看为人能否真实相通",subtitle:"真不是拒绝变化，清也不是排斥他物。",lines:[{text:"称道数当，故无择称之。",tone:"言说",guide:"田子方称赞谿工，是因为他的论说屡能切中。文本没有否定这项长处，也没有说可称赞者必定境界浅。后面的转折在于：人的完整成就，不只由若干正确的话组成。论说切当与为人真实可以相接，却不能直接互相替代。"},{text:"其为人也真。人貌而天虚。",tone:"真实",guide:"东郭顺子有人的形貌，却被写成精神虚静、自然。真与天虚连读，不是把他写成没有思想的空壳，而是不以自我造作、显名占据自身。也不必宣称他比《山木》的虚己高出一级：两处可以对读，但原文没有建立这样的等级。"},{text:"缘而葆真，清而容物。",tone:"相通",guide:"两组而字把看似容易分离的方面连起来：顺循情势，却不失根本；清明自持，却仍能容物。不是坚守自己就不能改变，也不是包容别人就必须失去判断。与《山木》形缘情率连读，可见顺应并非迎合，真实也不必成为封闭自守。"},{text:"物无道，正容以悟之，使人之意也消。",tone:"感发",guide:"面对不合道的人事，他先以自身端正的状态使人醒悟，不急于靠责斥取胜。这里突出德行与仪容的感发作用，但不能推成得道者只要出现，别人必然臣服。正容也不是神秘控制术，使意消解不等于取消对方全部意志。"},{text:"无择何足以称之！",tone:"称赞",guide:"这既有自谦，也显示田子方认为自己的称说不足以尽其师。不能只凭这句断言其师绝对不可言说：田子方已经给出了相当具体的描述。更适宜区分能够说明某些特点，与已经穷尽整个人的成就。"},{text:"吾所学者，直土埂耳！夫魏真为我累耳！",tone:"震动",guide:"文侯重新衡量自己的所学与所居之位，并感到魏国成为牵累。与《山木》鲁国之皮相接，君位不只提供权力，也造成执持与责任压力。但这是文侯受到震动后的感叹，不必当成文本要求所有君主放弃治理的制度方案，也不必取消他先前所学的一切价值。"}]}),t[5]||(t[5]=i('<h3 id="本段脉络" tabindex="-1">本段脉络 <a class="header-anchor" href="#本段脉络" aria-label="Permalink to &quot;本段脉络&quot;">​</a></h3><p><strong>谿工的论说切当 → 追问真正的老师 → 描写真实与全德 → 文侯重新衡量自身。</strong></p><p>东郭顺子的特点，可沿三条线索阅读：</p><table tabindex="0"><thead><tr><th>线索</th><th>核心句</th><th>阅读重点</th></tr></thead><tbody><tr><td>自身状态</td><td>人貌而天虚</td><td>不以形貌与自我造作决定全部</td></tr><tr><td>与物相处</td><td>缘而葆真，清而容物</td><td>顺应、真实、清明与包容相通</td></tr><tr><td>对人的作用</td><td>正容以悟之</td><td>感发不只来自正面说教</td></tr></tbody></table><p>这不是三个固定修养等级，而是同一人物的不同侧面。</p><p><strong>本段肯定的不只是少说话，而是言行、精神与应物之间的真实相接。</strong></p><h2 id="二、温伯雪子·礼义、人心与目击道存" tabindex="-1">二、温伯雪子·礼义、人心与目击道存 <a class="header-anchor" href="#二、温伯雪子·礼义、人心与目击道存" aria-label="Permalink to &quot;二、温伯雪子·礼义、人心与目击道存&quot;">​</a></h2><h3 id="原文-1" tabindex="-1">原文 <a class="header-anchor" href="#原文-1" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',8)),a(s,{sections:g,glossary:h,"default-mode":"classic","aria-label":"田子方·温伯雪子 原文"}),t[6]||(t[6]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"适齐",pinyin:["shì","qí"],meaning:"前往齐国。"},{term:"舍于鲁",pinyin:["shè","yú","lǔ"],meaning:"在鲁国住宿。舍读 shè。"},{term:"中国",pinyin:["zhōng","guó"],meaning:"古代中原地区的称呼。"},{term:"陋",pinyin:["lòu"],meaning:"浅陋、不充分。"},{term:"蕲",pinyin:["qí"],meaning:"求、请求。"},{term:"振我",pinyin:["zhèn","wǒ"],meaning:"振发、启发我等。"},{term:"道我",pinyin:["dǎo","wǒ"],meaning:"引导我。道联系导理解。"},{term:"目击而道存",pinyin:["mù","jī","ér","dào","cún"],meaning:"相见、目相接之际，已有真实相契。"},{term:"容声",pinyin:["róng","shēng"],meaning:"加入言声、以言声表达，整句有解释空间。"}]}),t[7]||(t[7]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"礼仪熟练，不自动等于理解眼前的人",subtitle:"目击道存不是取消语言，而是相见已经有所相契。",lines:[{text:"明乎礼义而陋于知人心。",tone:"检验",guide:"温伯雪子区分熟悉礼义与理解人心。一个人可以很知道应该怎样进退，却未必真正理解对方的处境与需要。但这首先是篇中人物的评价，不应扩大成中原人一概没有真情，或礼义本身必然遮蔽人心。问题在规范熟练是否转成了真实相处。"},{text:"是必有以振我也。",tone:"转变",guide:"先前拒见，后来因对方再次请求而愿意见面，显示温伯雪子并非始终封闭于自己的判断。他期待客人能够启发自己。这一转变也限制了只把本段读成高人拒绝俗人的简单图式：真正相处仍需面对实际来者。"},{text:"进退一成规、一成矩，从容一若龙、一若虎。",tone:"仪容",guide:"客人的动作仪容合乎成规，却仍使温伯雪子叹息。可以理解为交往被预设的仪节占满，但原文没有证明对方故意欺骗或内心全是假。较稳妥的重点是：动作合规与心意相通之间，仍可能存在距离。"},{text:"其谏我也似子，其道我也似父。",tone:"角色",guide:"对方规劝时像儿子，引导时又像父亲，交往不断落入子父角色般的关系。这可能显出他总从规范位置处理对方，而未能与具体的人相接。叹息不必只解释为礼节太多，也可以联系角色化的指导、规劝遮住了平等相遇。"},{text:"目击而道存矣，亦不可以容声矣！",tone:"相契",guide:"孔子见温伯雪子而不言，解释为相见之际已有道的呈现、心领相契。此处的沉默不同于客人的规矩繁多。但不能推出一眼就能知道任何人的全部境界，也不能说语言永远多余。第一段靠田子方的描述，第四段还将展开长篇问答；全篇是在辨明言说的作用与限度。"}]}),t[8]||(t[8]=i('<h3 id="与第一段连读" tabindex="-1">与第一段连读 <a class="header-anchor" href="#与第一段连读" aria-label="Permalink to &quot;与第一段连读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>第一段</th><th>第二段</th></tr></thead><tbody><tr><td>称道切当值得肯定，却不能尽人之真</td><td>礼义熟练不自动等于知人心</td></tr><tr><td>缘而葆真，清而容物</td><td>相见时是否真正与对方相接</td></tr><tr><td>正容能够感发</td><td>目击之际已有相契</td></tr><tr><td>称赞不足以尽其师</td><td>言声未必需要继续加入</td></tr></tbody></table><p><strong>两段不是一概反对语言与礼仪，而是拒绝让语言、礼仪代替真实相处。</strong></p><h2 id="三、颜渊问仲尼·追随旧迹与哀莫大于心死" tabindex="-1">三、颜渊问仲尼·追随旧迹与哀莫大于心死 <a class="header-anchor" href="#三、颜渊问仲尼·追随旧迹与哀莫大于心死" aria-label="Permalink to &quot;三、颜渊问仲尼·追随旧迹与哀莫大于心死&quot;">​</a></h2><h3 id="原文-2" tabindex="-1">原文 <a class="header-anchor" href="#原文-2" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',5)),a(s,{sections:m,glossary:_,"default-mode":"classic","aria-label":"田子方·颜渊问仲尼 原文"}),t[9]||(t[9]=n("blockquote",null,[n("p",null,[n("strong",null,"阅读说明："),e("「不化以待尽」「吾服，女也甚忘」「不忘者存」等有训释空间。以下抓住追随、变化与旧迹之间的关系，不把疑难句强行拼成唯一生死学说。")])],-1)),t[10]||(t[10]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"趋",pinyin:["qū"],meaning:"快步行走。"},{term:"驰",pinyin:["chí"],meaning:"疾行、奔跑。"},{term:"瞠",pinyin:["chēng"],meaning:"睁目而视。"},{term:"不比而周",pinyin:["bù","bǐ","ér","zhōu"],meaning:"不刻意亲附，却能周遍相合。"},{term:"恶",pinyin:["wū"],meaning:"此处为感叹词，不读美恶之 è。"},{term:"心死",pinyin:["xīn","sǐ"],meaning:"心的死滞，可联系失去随化应接的活力理解。"},{term:"日徂",pinyin:["rì","cú"],meaning:"一天天迁往、流逝。"},{term:"女",pinyin:["rǔ"],meaning:"通汝，你。"},{term:"唐肆",pinyin:["táng","sì"],meaning:"空肆、道路等，有不同训释。"},{term:"故吾",pinyin:["gù","wú"],meaning:"过去的我、已经显露的旧有样貌。"}]}),t[11]||(t[11]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"能够学到老师的话，却不能只沿老师的旧迹追赶",subtitle:"老师也在变化；真实相通不等于永久保存一个旧形象。",lines:[{text:"夫子步亦步，夫子趋亦趋，夫子驰亦驰。",tone:"追随",guide:"步、趋、驰被颜渊分别解释为言说、辩论、言道。他能够学习可辨认的表达，却在不言而信等作用面前感到追随不及。这不是实际行走比赛，也不必固定成四级修养阶梯，而是从可模仿的表现推进到难以复制的整体作用。"},{text:"不言而信，不比而周，无器而民滔乎前。",tone:"作用",guide:"颜渊看见老师不靠某种显设手段便与人相通，但自己不知道原因。不知所以然在这里首先是颜渊的认识状态，不能直接改成只有不知道才算全德。文本没有要求取消观察、学习或解释，而是显示复制言辞不足以复制一个人的全部成就。"},{text:"哀莫大于心死，而人死亦次之。",tone:"心死",guide:"结合下文对旧迹的追执，心死可联系心被固定表现拘住、失去随化应接的活力理解。不宜简单解释成没有热情、不再追求成功，更不能据此评价抑郁、哀伤中的人比死亡更失败。原文也没有在这里证明形体死后灵魂或道必然永存；心死应与后续变化论述连读。"},{text:"万物亦然，有待也而死，有待也而生。",tone:"有待",guide:"太阳的出入引出生命活动有所依待。存亡不是每到夜晚万物都死亡的字面事实，而是在描写显隐与活动条件。人不能独立于所有条件之外，老师也不是一种脱离变化、永远固定的存在。"},{text:"丘以是日徂。吾终身与汝交一臂而失之。",tone:"变化",guide:"孔子把自己放入流逝之中：即使长期相交，每一刻也已不完全是先前的样子。交臂而失不是简单断言师生情谊消失，而是提醒颜渊不要把已经呈现的老师，当成永远不变、可以追取的对象。"},{text:"彼已尽矣，而女求之以为有，是求马于唐肆也。",tone:"旧迹",guide:"已经过去的表现被继续索求，便向不宜求取的所在求取。唐肆的训释有差异，但譬喻的作用清楚：追逐旧迹，未必能与正在变化的老师相接。学习因此不只是记住他做过什么，也涉及理解他怎样面对新情势。"},{text:"虽忘乎故吾，吾有不忘者存。",tone:"根本",guide:"不必因旧我不能保留而惊惧，仍有不被旧迹完全穷尽的根本或真实相通可存。具体不忘者为何，有不同解释，可以联系道、德、应化的根本理解，却不能据此宣布已经论证个人永生。这里既松开追逐旧形象，也没有把师生之间的一切相通全部取消。"}]}),t[12]||(t[12]=i('<h3 id="本段的学习问题" tabindex="-1">本段的学习问题 <a class="header-anchor" href="#本段的学习问题" aria-label="Permalink to &quot;本段的学习问题&quot;">​</a></h3><p>可以把颜渊的困惑整理为：</p><p><strong>我能学他说的话，却不能只靠重复这些话，得到他与人相通的全部作用。</strong></p><p>孔子的回应又推进一步：</p><p><strong>你所追随的那个已经显露的老师，也在不断变化。</strong></p><p>因此，需要区别：</p><table tabindex="0"><thead><tr><th>学习旧迹</th><th>理解应化</th></tr></thead><tbody><tr><td>记住某一次回答</td><td>理解回答面对的情势</td></tr><tr><td>重复老师的说法</td><td>辨明此刻是否仍适用</td></tr><tr><td>保存一个固定形象</td><td>承认相交者也在变化</td></tr><tr><td>以追随成功证明自己</td><td>保留重新理解与应接的活力</td></tr></tbody></table><p>记忆与模仿可以有用，但不能因此代替全部学习。</p><p><strong>本段不是劝人停止学，而是防止学习退化成对旧迹的追逐。</strong></p><h2 id="四、孔子见老聃·游心于物之初与自然之德" tabindex="-1">四、孔子见老聃·游心于物之初与自然之德 <a class="header-anchor" href="#四、孔子见老聃·游心于物之初与自然之德" aria-label="Permalink to &quot;四、孔子见老聃·游心于物之初与自然之德&quot;">​</a></h2><h3 id="原文-3" tabindex="-1">原文 <a class="header-anchor" href="#原文-3" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',11)),a(s,{sections:u,glossary:f,"default-mode":"classic","aria-label":"田子方·孔子见老聃 原文"}),t[13]||(t[13]=n("blockquote",null,[n("p",null,[n("strong",null,"文字说明："),e("「掘若槁木」「不疾易薮」「弃隶」「汋」等有异文或训释问题。原文保留来稿，不将「隶」直接定为爵位，也不把「不修」直接化成禁止学习与修养。")])],-1)),t[14]||(t[14]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"新沐",pinyin:["xīn","mù"],meaning:"刚洗头。"},{term:"被发",pinyin:["pī","fà"],meaning:"披散头发，被通披。"},{term:"蛰然",pinyin:["zhé","rán"],meaning:"静止不动的样子。"},{term:"物之初",pinyin:["wù","zhī","chū"],meaning:"万物生成的根本、初始。"},{term:"消息",pinyin:["xiāo","xī"],meaning:"消减与生长，不是现代信息义。"},{term:"薮",pinyin:["sǒu"],meaning:"草泽、草木丛生之处。"},{term:"大常",pinyin:["dà","cháng"],meaning:"根本常道、生命所循的基本条件。"},{term:"滑",pinyin:["gǔ"],meaning:"扰乱。"},{term:"汋",pinyin:["zhuó"],meaning:"水流动、涌出等，具体训释有差异。"},{term:"醯鸡",pinyin:["xī","jī"],meaning:"醋瓮中的小虫，借喻受遮限的见识。"},{term:"发吾覆",pinyin:["fā","wú","fù"],meaning:"揭开遮住我的覆盖物。"}]}),t[15]||(t[15]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"游心于生成变化的根本，不把德当成外加的装饰",subtitle:"静止的外貌不等于心死，自然之德也不等于无所作为。",lines:[{text:"蛰然似非人……似遗物离人而立于独也。",tone:"所见",guide:"孔子由老聃静止的外貌发问，随后才知道他在游心。与前段心死对读，不能只凭动作少、看似枯木，就认定精神死滞。外貌需要结合其实际状态理解；立于独也不是永远拒绝别人，因为老聃接着与孔子展开问答。"},{text:"吾游心于物之初。心困焉而不能知，口辟焉而不能言。",tone:"本源",guide:"物之初指向生成的根本，不是一个可以直接描画的对象。不能知、不能言表达穷尽它的困难，但老聃仍尝试议乎其将。因此，这里不是完全取消认识和表达，而是保留表达只是近似、不能尽其所述的自觉。"},{text:"两者交通成和而物生焉，或为之纪而莫见其形。",tone:"生成",guide:"阴阳交汇成和，万物由此生成；其条理可见，作为根本的形体却不可见。或为之纪不必解释成人格神主宰一切。也不宜把这段直接当作现代物理理论，它首先是古代语境中对生成、消长与终始的描述。"},{text:"始终相反乎无端，而莫知乎其所穷。",tone:"无端",guide:"生有萌发，死有所归，终始相续而难见尽头。与《山木》正而待之可以相接，但不能机械地分成山木只静、这里只动。游心与应待都涉及不强把变化收成一条自己能够完全控制的线。"},{text:"得至美而游乎至乐，谓之至人。",tone:"至人",guide:"这里将通达生成根本与至美至乐相接。游不是把道作为财物占有，而是自在与之相往来。至人是本段明确的命名，但不能说这是本篇第一次出现至人：前段无器、不言的对话也涉及相近主题，严格名词出现仍须依全文检查。更不宜把全德之君子与至人定成两个已明确排序的等级。"},{text:"行小变而不失其大常也，喜怒哀乐不入于胸次。",tone:"常变",guide:"更换草泽、水域属于小变，生命所循的基本条件仍可保持。重点不是禁止迁移，而是变化中不失根本。不入胸次可联系不被喜怒哀乐长期占据、扰乱，不必解释成至人没有感情，更不是要求人在痛苦时强行压抑情绪。"},{text:"死生终始将为昼夜，而莫之能滑。",tone:"死生",guide:"昼夜譬喻把死生终始放回变化之中，缓解以单一阶段为全部的执持。四支百体如尘垢是强烈表达，不是要求轻贱身体、忽略健康；也不能据此证明个体死后永远以同一人格继续存在。"},{text:"贵在于我而不失于变。",tone:"所贵",guide:"与隶、泥涂相对，强调自身所贵不应完全由外在附属、势位决定。隶的具体解释有争议，不直接定为爵位。可以先把握：某种外在依凭失去，不等于自身全部价值随之失去。"},{text:"至人之于德也，不修而物不能离焉。",tone:"自然",guide:"孔子把老聃的说明理解成借至言修心，老聃以不然纠正：德的作用如水之作用、天高地厚，不是额外加工成一个可展示的样子。但这不等于对一切学习、养护与修正都发出禁令。所反对的是把自然通达当成外加装饰，或靠刻意表现维持。"},{text:"微夫子之发吾覆也，吾不知天地之大全也。",tone:"开覆",guide:"醯鸡受瓮盖限制，孔子借此承认先前认识的局限。开覆意味着原有尺度被打开，不必夸大成从此已经穷尽全部天地知识。此处的开解也确实借助问答发生，不能总结成老聃全程无需言语、只靠存在就完成教化。"}]}),t[16]||(t[16]=i('<h3 id="本段三条线索" tabindex="-1">本段三条线索 <a class="header-anchor" href="#本段三条线索" aria-label="Permalink to &quot;本段三条线索&quot;">​</a></h3><h4 id="_1-言说的限度" tabindex="-1">1. 言说的限度 <a class="header-anchor" href="#_1-言说的限度" aria-label="Permalink to &quot;1. 言说的限度&quot;">​</a></h4><p><strong>不能尽知尽言 → 仍尝试议其大概。</strong></p><p>不因为难以穷尽，就拒绝一切解释；也不因能够描述，就认定已经掌握全部。</p><h4 id="_2-常与变的关系" tabindex="-1">2. 常与变的关系 <a class="header-anchor" href="#_2-常与变的关系" aria-label="Permalink to &quot;2. 常与变的关系&quot;">​</a></h4><p><strong>消息满虚、日改月化 → 行小变而不失大常。</strong></p><p>根本不必等于某一种固定外形，变化也不必等于失去一切依据。</p><h4 id="_3-德的自然作用" tabindex="-1">3. 德的自然作用 <a class="header-anchor" href="#_3-德的自然作用" aria-label="Permalink to &quot;3. 德的自然作用&quot;">​</a></h4><p><strong>误认为借言修心 → 以水、天地、日月说明不修而自然。</strong></p><p>「不修」首先针对人为加工、自我造作的理解，不应直接改成：</p><p><strong>不必学习、不必反省、不必照料身体。</strong></p><p>本段的重点是：</p><p><strong>不把通达另做成一种供自己展示和占有的成就。</strong></p><h2 id="五、庄子与鲁哀公·儒服不等于儒道" tabindex="-1">五、庄子与鲁哀公·儒服不等于儒道 <a class="header-anchor" href="#五、庄子与鲁哀公·儒服不等于儒道" aria-label="Permalink to &quot;五、庄子与鲁哀公·儒服不等于儒道&quot;">​</a></h2><h3 id="原文-4" tabindex="-1">原文 <a class="header-anchor" href="#原文-4" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',15)),a(s,{sections:b,glossary:y,"default-mode":"classic","aria-label":"田子方·儒服与儒道 原文"}),t[17]||(t[17]=n("blockquote",null,[n("p",null,"**历史与寓言说明：**鲁哀公属于春秋末期，庄子属于战国时期，两人的年代不相合。本段不宜当作真实会面记录。严酷号令服务于故事反转，也不能直接作为现实治理建议。")],-1)),t[18]||(t[18]=n("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"方",pinyin:["fāng"],meaning:"方术、学说、道路。"},{term:"举鲁国",pinyin:["jǔ","lǔ","guó"],meaning:"全鲁国。举：全。"},{term:"冠圜冠",pinyin:["guàn","yuán","guān"],meaning:"戴圆帽；前冠动词，后冠名词。"},{term:"句履",pinyin:["jù","lǚ"],meaning:"鞋名，常释方头鞋，形制与音读有讨论。"},{term:"玦",pinyin:["jué"],meaning:"有缺口的环形玉器，文中与决断关联。"},{term:"号",pinyin:["hào"],meaning:"发布号令。"},{term:"丈夫",pinyin:["zhàng","fū"],meaning:"成年男子，不只指配偶身份。"},{term:"千转万变",pinyin:["qiān","zhuǎn","wàn","biàn"],meaning:"问答变化繁多，仍能应对。"}]}),t[19]||(t[19]=n("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"标志可以指向能力，却不能代替能力",subtitle:"不是服饰没有意义，而是不能只凭服饰计数有道之人。",lines:[{text:"举鲁国而儒服，何谓少乎？",tone:"计数",guide:"哀公以穿儒服者的数量判断儒者多，庄子则要求分辨服饰与真实所能。问题不是一个人该不该穿这种衣服，而是可见标志是否足以证明内在理解与实际能力。"},{text:"君子有其道者，未必为其服也；为其服者，未必知其道也。",tone:"分辨",guide:"两个未必很重要：有道者可能不穿，穿者可能不知。它不是说所有穿儒服的人都无道，也不是说形式永远无法表达实质。服饰不是充分凭据，也不必成为绝对必要条件；判断仍需回到具体理解和行动。"},{text:"无此道而为此服者，其罪死！",tone:"设令",guide:"故事用极端命令使原先遍国可见的标志迅速消失，形成反转。不能把它整理成庄子主张处死穿错衣服者的政策。恐惧也会改变人的行为，所以现实中不敢穿服并不能可靠证明无能；本段主要依寓言夸张检验名实混同。"},{text:"问以国事，千转万变而不穷。",tone:"应事",guide:"留下的一人不仅穿儒服，还能应答变化繁多的国事。故事并未把所有儒者都抹除，反而保留真实所能的肯定。这个所能也不宜立即等同前段老聃之至人：本段检验的是儒服与儒道相称。"},{text:"以鲁国而儒者一人耳，可谓多乎？",tone:"反转",guide:"末句回到最初多与少的争论：遍国的服饰数量，不等于真正成就的数量。不必再反说一个才是真正的多，原文恰是问可谓多乎。它要求改变计数标准，而不是把数量概念神秘化。"}]}),t[20]||(t[20]=i('<h3 id="本段与前四段的关系" tabindex="-1">本段与前四段的关系 <a class="header-anchor" href="#本段与前四段的关系" aria-label="Permalink to &quot;本段与前四段的关系&quot;">​</a></h3><p>前几段已经区分：</p><p><strong>言说，与为人。</strong></p><p><strong>仪节，与知人心。</strong></p><p><strong>旧迹，与正在变化的老师。</strong></p><p>本段再加入：</p><p><strong>服饰标志，与真实所能。</strong></p><p>这些区分都不是把可见形式判成无价值，而是：</p><blockquote><p><strong>形式可以提供线索，却不能独自完成判断。</strong></p></blockquote><h2 id="六、百里奚与有虞氏·爵禄、死生不入于心" tabindex="-1">六、百里奚与有虞氏·爵禄、死生不入于心 <a class="header-anchor" href="#六、百里奚与有虞氏·爵禄、死生不入于心" aria-label="Permalink to &quot;六、百里奚与有虞氏·爵禄、死生不入于心&quot;">​</a></h2><h3 id="原文-5" tabindex="-1">原文 <a class="header-anchor" href="#原文-5" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',11)),a(s,{sections:c,glossary:z,"default-mode":"classic","aria-label":"田子方·百里奚与有虞氏 原文"}),t[21]||(t[21]=n("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"百里奚",pinyin:["bǎi","lǐ","xī"],meaning:"传统记载中的秦穆公贤臣。"},{term:"爵禄",pinyin:["jué","lù"],meaning:"爵位与俸禄。"},{term:"饭牛",pinyin:["fàn","niú"],meaning:"喂牛、养牛。饭作动词。"},{term:"忘其贱",pinyin:["wàng","qí","jiàn"],meaning:"不再以原先卑下身份限制对他的评价。"},{term:"与之政",pinyin:["yǔ","zhī","zhèng"],meaning:"授予政事，让他参与治理。"},{term:"有虞氏",pinyin:["yǒu","yú","shì"],meaning:"舜的称号。"},{term:"动人",pinyin:["dòng","rén"],meaning:"使人受到感发。"}]}),t[22]||(t[22]=n("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"不以爵禄占心，却仍能把眼前的事做好",subtitle:"不入于心不是不关心，而是不让它成为支配自身的唯一尺度。",lines:[{text:"百里奚爵禄不入于心，故饭牛而牛肥。",tone:"做事",guide:"短章把不以爵禄为念与养牛有成联系起来，显示不受名位拘系并不等于消极。可以理解为他不因身份而轻忽眼前事务，但原文没有逐项交代其心理活动，不能补成他毫无任何愿望。更不能推出只要专注当下，爵禄就一定自然到来。"},{text:"使秦穆公忘其贱，与之政也。",tone:"识人",guide:"穆公不以原先卑下身份穷尽百里奚，转而看见他的实际所能。与儒服故事相接，身份标志不能代替能力判断。这里仍是故事中的际遇，不是所有认真做事者都会被权力发现、获得晋升的保证。"},{text:"有虞氏死生不入于心，故足以动人。",tone:"感发",guide:"舜不以死生之虑拘系心神，因而能感发他人。它与百里奚构成外在名位、生命存亡两种牵系的并列，不必定成严格高低等级。足以动人也不能改成无需行为、只要存在就有超自然力量；前句养牛恰已明确写出实际行动。"}]}),t[23]||(t[23]=i(`<h3 id="两种「不入于心」" tabindex="-1">两种「不入于心」 <a class="header-anchor" href="#两种「不入于心」" aria-label="Permalink to &quot;两种「不入于心」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物</th><th>不入于心者</th><th>故事呈现的作用</th></tr></thead><tbody><tr><td>百里奚</td><td>爵禄</td><td>不因名位轻忽事务，养牛有成</td></tr><tr><td>有虞氏</td><td>死生</td><td>不被存亡之虑拘系，能够感发人</td></tr></tbody></table><p>两者共同说明：</p><p><strong>不把某件事放成心的唯一主宰，不等于对生活毫无关心。</strong></p><p>百里奚仍在养牛，后来仍参与政事；「不入于心」与具体行动相接，而不是以无所作为证明超脱。</p><h2 id="一至六段·阶段性脉络" tabindex="-1">一至六段·阶段性脉络 <a class="header-anchor" href="#一至六段·阶段性脉络" aria-label="Permalink to &quot;一至六段·阶段性脉络&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段：田子方与魏文侯</span></span>
<span class="line"><span>    称道切当 → 追问其师</span></span>
<span class="line"><span>    → 人貌天虚、缘而葆真、清而容物</span></span>
<span class="line"><span>    → 文侯重新衡量所学与君位</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第2段：温伯雪子</span></span>
<span class="line"><span>    明乎礼义 → 未必知人心</span></span>
<span class="line"><span>    规矩仪容 → 未必真实相契</span></span>
<span class="line"><span>    → 仲尼见而不言，目击而道存</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第3段：颜渊与仲尼</span></span>
<span class="line"><span>    能随言辩 → 难以复制整体作用</span></span>
<span class="line"><span>    → 老师亦在流逝</span></span>
<span class="line"><span>    → 不追执故吾，保留真实相通</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第4段：孔子见老聃</span></span>
<span class="line"><span>    由静止外貌发问 → 游心于物之初</span></span>
<span class="line"><span>    → 生成变化、至美至乐、常与变</span></span>
<span class="line"><span>    → 不将自然之德误作额外加工</span></span>
<span class="line"><span>    → 揭开认识的遮限</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第5段：儒服与儒道</span></span>
<span class="line"><span>    服饰数量 → 不等于真实成就数量</span></span>
<span class="line"><span>    → 有其道未必为其服</span></span>
<span class="line"><span>    → 判断回到实际所知与所能</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第6段：百里奚与有虞氏</span></span>
<span class="line"><span>    爵禄不入于心 → 仍认真办事</span></span>
<span class="line"><span>    死生不入于心 → 能够感发</span></span>
<span class="line"><span>    → 不受牵系，不等于无所行动</span></span></code></pre></div><h3 id="阶段性收束" tabindex="-1">阶段性收束 <a class="header-anchor" href="#阶段性收束" aria-label="Permalink to &quot;阶段性收束&quot;">​</a></h3><p>前六段反复辨明：</p><p><strong>说得切当，不等于已经尽其为人。</strong></p><p><strong>动作合礼，不等于已经知人心。</strong></p><p><strong>重复旧迹，不等于真正随化而学。</strong></p><p><strong>穿着其服，不等于拥有其道。</strong></p><p><strong>不念爵禄，不等于不肯做事。</strong></p><p>但它们也没有简单取消：</p><ul><li>论说。</li><li>问答。</li><li>学习。</li><li>仪容。</li><li>实际办事。</li></ul><p>这些形式与行动需要回到真实的根本，而不能反过来代替它。</p><p>这六段暂可收在一句话上：</p><blockquote><p><strong>真实成就不止于可见标志，也不脱离具体行动；顺循而葆真，清明而容物，才能使形式与生命重新相接。</strong></p></blockquote><h2 id="七、宋元君与画史·解衣般礴与真画者" tabindex="-1">七、宋元君与画史·解衣般礴与真画者 <a class="header-anchor" href="#七、宋元君与画史·解衣般礴与真画者" aria-label="Permalink to &quot;七、宋元君与画史·解衣般礴与真画者&quot;">​</a></h2><h3 id="原文-6" tabindex="-1">原文 <a class="header-anchor" href="#原文-6" aria-label="Permalink to &quot;原文&quot;">​</a></h3>`,21)),a(s,{sections:x,glossary:q,"default-mode":"classic","aria-label":"田子方·宋元君与画史 原文"}),t[24]||(t[24]=n("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"史",pinyin:["shǐ"],meaning:"此处指画史、画师。"},{term:"揖",pinyin:["yī"],meaning:"礼仪动作，受揖的具体含义有不同解释。"},{term:"舐",pinyin:["shì"],meaning:"舔。舐笔和墨：准备笔墨。"},{term:"儃儃然",pinyin:["tǎn","tǎn","rán"],meaning:"从容舒缓的样子，读音宜依注本统一。"},{term:"趋",pinyin:["qū"],meaning:"快步趋进。"},{term:"之舍",pinyin:["zhī","shè"],meaning:"往舍处。之：往；舍：居处。"},{term:"般礴",pinyin:["pán","bó"],meaning:"舒展、箕踞等，坐姿有不同训释。"},{term:"裸",pinyin:["luǒ"],meaning:"身体裸露。"}]}),t[25]||(t[25]=n("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"能否进入创作，不只看是否摆好了作画的样子",subtitle:"解衣般礴写不拘束，不是创作必须裸体的规则。",lines:[{text:"受揖而立，舐笔和墨，在外者半。",tone:"准备",guide:"众画师到场、站立、准备笔墨，这是正常的作画准备。故事以其整齐与后至者的舒放形成对照，但不能直接判定所有准备者都在欺骗、奉承或毫无真实技艺。问题在于准备姿态能否单独证明创作成就。"},{text:"儃儃然不趋，受揖不立，因之舍。",tone:"从容",guide:"后至者不急于趋进，也没有继续立在众人之间，转而往舍处。这显示他不被召见场面的紧张拘束，不必补写为故意迟到、蔑视君主或拒绝任务。原文重心在其状态，而不是赞美违约和不合作。"},{text:"解衣般礴裸。",tone:"舒放",guide:"君主派人查看时，他解衣舒坐、裸露身体。可以联系卸除过度拘束、回到自在创作状态理解，却不能把衣服一律视为虚假，也不能反推只有脱去衣服才有道。与儒服故事相接，关键是形式不是充分凭据，不是裸体成为新的凭据。"},{text:"可矣，是真画者也。",tone:"识人",guide:"宋元君在作品尚未呈现时，先从状态判断他是真画者。寓言强调创作所需的舒放与不自矜，不提供现实鉴定画家的可靠测试。真正评价作品与专业能力，仍需具体成果；有礼、守流程的画师也可能有真才。"}]}),t[26]||(t[26]=i('<h3 id="与前六段连读" tabindex="-1">与前六段连读 <a class="header-anchor" href="#与前六段连读" aria-label="Permalink to &quot;与前六段连读&quot;">​</a></h3><p><strong>儒服不等于儒道。</strong></p><p><strong>准备作画的姿态，也不等于已经进入真实创作。</strong></p><p>两段共同限制的是<strong>只凭外在标志识人</strong>，而不是宣布：</p><p><strong>穿衣无道，脱衣有道。</strong></p><p>解衣般礴所呈现的舒放，也不是完全没有训练；故事没有交代画者的学习过程，不宜因此抹去技艺所需的积累。</p><h2 id="八、文王与臧丈人·常钓、授政与循斯须" tabindex="-1">八、文王与臧丈人·常钓、授政与循斯须 <a class="header-anchor" href="#八、文王与臧丈人·常钓、授政与循斯须" aria-label="Permalink to &quot;八、文王与臧丈人·常钓、授政与循斯须&quot;">​</a></h2><h3 id="原文-7" tabindex="-1">原文 <a class="header-anchor" href="#原文-7" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',8)),a(s,{sections:k,glossary:P,"default-mode":"classic","aria-label":"田子方·文王与臧丈人 原文"}),t[27]||(t[27]=n("blockquote",null,[n("p",null,[n("strong",null,"阅读说明："),e("「常钓」「斔斛」「朝令而夜循」与末句「彼」的所指，均有训释空间。以下保留故事中的张力，不直接把文王判为低一等，也不将臧丈人的政治作用解释为全无行动。")])],-1)),t[28]||(t[28]=n("h3",{id:"生僻字词-7",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"臧",pinyin:["zāng"],meaning:"篇中地名，具体位置不强定。"},{term:"属",pinyin:["zhǔ"],meaning:"告语、嘱告。"},{term:"髯",pinyin:["rán"],meaning:"胡须。"},{term:"寓而政",pinyin:["yù","rǔ","zhèng"],meaning:"寄托你的政事；而联系汝理解。"},{term:"瘳",pinyin:["chōu"],meaning:"病愈、好转，借喻民生改善。"},{term:"蹴然",pinyin:["cù","rán"],meaning:"惊动、肃然的样子。"},{term:"斔斛",pinyin:["yǔ","hú"],meaning:"量器，整句政治含义有不同解释。"},{term:"四竟",pinyin:["sì","jìng"],meaning:"四境，竟通境。"},{term:"论剌",pinyin:["lùn","cì"],meaning:"论议、讥刺。"},{term:"斯须",pinyin:["sī","xū"],meaning:"片刻、一时。"}]}),t[29]||(t[29]=n("h3",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"不把治理据为己功，也不把一时之应固化为普遍公式",subtitle:"常钓与循斯须，须连同任用、治理和辞去一起看。",lines:[{text:"其钓莫钓……常钓也。",tone:"常钓",guide:"开头用反常措辞写臧丈人的钓，常可联系不以求得、求用拘住自己的活动理解。但原文没有证明他毫无一切目的，文王如何从钓者识得其人也未展开。不能直接把他认作历史上的姜太公，或把常钓整理成做任何事都不许有目标。"},{text:"恐大臣父兄之弗安……不忍百姓之无天。",tone:"两难",guide:"文王既担心任用引发不安，又不忍百姓失去改善处境的机会。梦境叙述使大夫接受任用，后文颜渊正追问为何用梦。文本因此保留了政治权威、因时应变与真实性之间的张力，而不是只写文王有为所以必然低于臧丈人。"},{text:"典法无更，偏令无出。",tone:"治理",guide:"典法未更、没有偏令，说明治理不以频繁改法和私意命令显示存在。但臧丈人已经受政，故事又叙述三年效果，不能由没有改法推成什么都没做。维持秩序、协调关系与不据功自成，也可能是行动方式。"},{text:"列士坏植散群，则尚同也；长官者不成德，则同务也。",tone:"相协",guide:"文本用尚同、同务解释治理效果：私群与自立减弱，官员不独据其德，而共同办事。坏植、不成德的具体训释有差异，较稳妥的是按后句看其方向。也不能把尚同直接变成现代社会必须压制所有不同意见的原则。"},{text:"政可以及天下乎？……泛然而辞，终身无闻。",tone:"辞去",guide:"文王希望了解能否推及天下，臧丈人不答而辞去。可以联系不愿把所得变成名位、普遍方案或持续权力理解，但原文没有说明他认定问题毫无答案。沉默与退去保留开放性，不能把推及天下一概判为错误。"},{text:"夫文王尽之也，而又何论剌焉！彼直以循斯须也。",tone:"因时",guide:"孔子明确为文王辩护，限制了前文将梦境只作局限的理解。彼的所指有不同解释，循斯须可联系顺循一时条件、因时处理。它不等于不关心未来，也不等于片刻足以解决所有政治问题，而是提醒评价不能脱离实际情势。"}]}),t[30]||(t[30]=i('<h3 id="本段保留的张力" tabindex="-1">本段保留的张力 <a class="header-anchor" href="#本段保留的张力" aria-label="Permalink to &quot;本段保留的张力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>一面</th><th>另一面</th></tr></thead><tbody><tr><td>任用贤者改善民生</td><td>仍须面对大臣与既有权威</td></tr><tr><td>不更法、不出偏令</td><td>并不因此取消治理职责</td></tr><tr><td>治理已有成效</td><td>不必据其功建立永久身份</td></tr><tr><td>希望推广其政</td><td>实际回应未必能直接变成公式</td></tr><tr><td>颜渊质疑梦境</td><td>孔子强调文王已经因时尽力</td></tr></tbody></table><p><strong>本段不是一张“文王有为、臧丈人无为”的简单高下表，而是在治理的现实条件中检验不强作、不据功与因时应变。</strong></p><h2 id="九、列御寇射箭·射之射与不射之射" tabindex="-1">九、列御寇射箭·射之射与不射之射 <a class="header-anchor" href="#九、列御寇射箭·射之射与不射之射" aria-label="Permalink to &quot;九、列御寇射箭·射之射与不射之射&quot;">​</a></h2><h3 id="原文-8" tabindex="-1">原文 <a class="header-anchor" href="#原文-8" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',5)),a(s,{sections:w,glossary:T,"default-mode":"classic","aria-label":"田子方·列御寇射箭 原文"}),t[31]||(t[31]=n("blockquote",null,[n("p",null,"**安全与释义说明：**临深渊是寓言中的极端场景，不可模仿。「中」有射中目标与内在状态等解释，不强定为“真正危险只在内心”。")],-1)),t[32]||(t[32]=n("h3",{id:"生僻字词-8",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"盈贯",pinyin:["yíng","guàn"],meaning:"拉弓至满。"},{term:"措",pinyin:["cuò"],meaning:"放置。"},{term:"复沓",pinyin:["fù","tà"],meaning:"连续相继，具体射箭动作有训释差异。"},{term:"象人",pinyin:["xiàng","rén"],meaning:"偶人、人像，形容动作稳定。"},{term:"仞",pinyin:["rèn"],meaning:"古代长度单位，此处极言深渊之深。"},{term:"逡巡",pinyin:["qūn","xún"],meaning:"缓缓退移。"},{term:"踵",pinyin:["zhǒng"],meaning:"脚后跟。"},{term:"挥斥",pinyin:["huī","chì"],meaning:"奔放、游行等。"},{term:"恂目",pinyin:["xún","mù"],meaning:"惊惧、目光失稳等。"},{term:"殆",pinyin:["dài"],meaning:"危险、不可靠，亦可有推测语气。"}]}),t[33]||(t[33]=n("h3",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"熟练动作，不等于在所有情境中都能保持同样的状态",subtitle:"恐惧会影响表现，但深渊本身也确有危险。",lines:[{text:"措杯水其肘上……当是时，犹象人也。",tone:"熟练",guide:"列御寇拉弓、接续发射而保持稳定，表现出很高的技艺。伯昏无人接着提出另一种检验，并没有证明这些训练毫无价值。原文也未明说这是平地，只能先称为原先的射箭场景，与后来临渊对照。"},{text:"是射之射，非不射之射也。",tone:"辨别",guide:"可把射之射理解为心中执持射、以射为意的射；不射之射则指不被射的自我意识、成败之虑拘系。不能直接分成清醒与无意识，亦不是忘掉安全规则、拒绝训练。不射之射仍然是射，所松开的是对动作与成败的过度拘持。"},{text:"御寇伏地，汗流至踵。",tone:"临渊",guide:"场景改变后，列御寇恐惧伏地。说明原先稳定未能原样迁移到极端情境，但不是能力突然完全消失。现实中远离深渊、降低风险是合理判断，不应把正常恐惧判成道德失败，更不能为了证明神气不变去冒险。"},{text:"挥斥八极，神气不变。",tone:"理想",guide:"伯昏无人以青天、黄泉、八极描写至人的精神通达，突出不被情境轻易夺其根本。这是夸张的理想意象，不等于肉身不依赖任何环境，也不保证至人在缺氧、坠落等危险中不受伤。"},{text:"尔于中也殆矣夫！",tone:"影响",guide:"中若按射中理解，句意可指此刻命中已不可靠；若联系内在，则强调心神受扰。无论采用哪一种，都不宜推成外在深渊不是危险、只有内心恐惧危险。文本检验的是情境、心神与技艺之间的关联。"}]}),t[34]||(t[34]=i('<h3 id="与《山木》腾猿对读" tabindex="-1">与《山木》腾猿对读 <a class="header-anchor" href="#与《山木》腾猿对读" aria-label="Permalink to &quot;与《山木》腾猿对读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>腾猿故事</th><th>列御寇故事</th></tr></thead><tbody><tr><td>换到荆棘，攀援受限</td><td>换到深渊边，射箭状态受扰</td></tr><tr><td>强调处势不便</td><td>强调心神与技艺的关系</td></tr><tr><td>不因受限便断言无能</td><td>不因熟练便断言处处可靠</td></tr></tbody></table><p>二者共同说明：<strong>表现需要放在具体条件中判断。</strong></p><p>但侧重不同，不能合并成：</p><p><strong>技艺都无用，得道就完全不依赖环境。</strong></p><p>真正可引申的方向，是辨明条件、训练迁移与心理负荷，而不是否认危险。</p><h2 id="十、孙叔敖三为三去·得失之非我" tabindex="-1">十、孙叔敖三为三去·得失之非我 <a class="header-anchor" href="#十、孙叔敖三为三去·得失之非我" aria-label="Permalink to &quot;十、孙叔敖三为三去·得失之非我&quot;">​</a></h2><h3 id="原文-9" tabindex="-1">原文 <a class="header-anchor" href="#原文-9" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',8)),a(s,{sections:j,glossary:S,"default-mode":"classic","aria-label":"田子方·孙叔敖三为三去 原文"}),t[35]||(t[35]=n("h3",{id:"生僻字词-9",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"令尹",pinyin:["lìng","yǐn"],meaning:"楚国重要执政官名。"},{term:"栩栩然",pinyin:["xǔ","xǔ","rán"],meaning:"舒畅自得的样子。"},{term:"却",pinyin:["què"],meaning:"推却、退却。"},{term:"亡",pinyin:["wú"],meaning:"此处通无，不作死亡解。"},{term:"踌躇",pinyin:["chóu","chú"],meaning:"徘徊、舒徐或思量等，依语境理解。"},{term:"说",pinyin:["shuì"],meaning:"劝说。知者不得说。"},{term:"滥",pinyin:["làn"],meaning:"侵乱、迷乱等。"},{term:"伏戏",pinyin:["fú","xī"],meaning:"伏羲的异写。"},{term:"濡",pinyin:["rú"],meaning:"沾湿。"},{term:"介",pinyin:["jiè"],meaning:"阻隔、妨碍等。"}]}),t[36]||(t[36]=n("h3",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"职位可以改变，不必随之把自身价值全部重写",subtitle:"不以得失立己，仍然可以任职、办事与给予。",lines:[{text:"三为令尹而不荣华，三去之而无忧色。",tone:"得失",guide:"肩吾观察孙叔敖任职与离职时的状态，注意到他没有以升任自荣、以离职失色。不是说他毫无情感，也不是仅凭外貌就证明绝无忧虑。故事接着让本人解释，把重点转到他如何理解职位与自身。"},{text:"吾以为得失之非我也。",tone:"非我",guide:"职位得失不是自己能全然控制的，也不等于自身全部。不能把非我推成任免完全与个人能力、行动无关；较稳妥的是，不将外在职位的来去全部据为固有的我。此句也不证明存在一个永远不变的实体灵魂。"},{text:"其来不可却也，其去不可止也。",tone:"来去",guide:"孙叔敖承认这段际遇中的来去条件，不以一己执持强留。它不是普遍命令任何职务都必须接受，也不是说面对不公离职不可申辩。与原文的具体任职经验相接，重点在不把职位保有当成自我安顿的唯一根据。"},{text:"何暇至乎人贵人贱哉！",tone:"评价",guide:"彼我、贵的所在有训释空间，末句则明确松开对他人贵贱评价的专注。踌躇四顾不必解释成忙得没有时间关心，更不能因此定为比《山木》无责于人更高一级。这里是不让评价穷尽自己的注意与生活。"},{text:"死生亦大矣，而无变乎己，况爵禄乎！",tone:"真人",guide:"孔子从职位得失推举到真人的生命安顿。死生都不足以夺其根本，何况爵禄，是理想化的递进表达。它并非取消身体会死亡的事实，也不要求现实中失去工作的人必须毫无痛苦。"},{text:"其神经乎大山而无介，入乎渊泉而不濡。",tone:"精神",guide:"句子以其神为主语，用山、渊与卑细写精神不受阻染。不能按肉身穿山、防水和不受伤解，也不必给真人与至人规定内外两套固定定义。两种称谓在本篇相互呼应，仍须依各段语境理解。"},{text:"既以与人己愈有。",tone:"给予",guide:"给予他人，自己反而更充实，可联系德行、关怀和共同生活的成就理解。它不是有限资源的数量规律：时间、金钱与精力仍可能耗损。真实给予需要边界，不能以愈有要求人无止境付出。"}]}),t[37]||(t[37]=i('<h3 id="与第六段连读" tabindex="-1">与第六段连读 <a class="header-anchor" href="#与第六段连读" aria-label="Permalink to &quot;与第六段连读&quot;">​</a></h3><p>第六段说：</p><blockquote><p><strong>爵禄不入于心。</strong></p></blockquote><p>第十段展开为：</p><blockquote><p><strong>得失之非我。</strong></p></blockquote><p>两处都没有取消实际行动：</p><ul><li>百里奚养牛，后来参与政事。</li><li>孙叔敖任职，也能面对离职。</li><li>真人的描述最后转向给予他人。</li></ul><p><strong>不以职位立己，不是拒绝一切职责；不被得失穷尽，也不意味着不必承担实际后果。</strong></p><h2 id="十一、楚王与凡君·国之存亡不尽吾存" tabindex="-1">十一、楚王与凡君·国之存亡不尽吾存 <a class="header-anchor" href="#十一、楚王与凡君·国之存亡不尽吾存" aria-label="Permalink to &quot;十一、楚王与凡君·国之存亡不尽吾存&quot;">​</a></h2><h3 id="原文-10" tabindex="-1">原文 <a class="header-anchor" href="#原文-10" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',10)),a(s,{sections:A,glossary:C,"default-mode":"classic","aria-label":"田子方·楚王与凡君 原文"}),t[38]||(t[38]=n("h3",{id:"生僻字词-10",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-10","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"凡君",pinyin:["fán","jūn"],meaning:"凡国之君，具体历史身份不强定。"},{term:"左右",pinyin:["zuǒ","yòu"],meaning:"身旁侍从。"},{term:"少焉",pinyin:["shǎo","yān"],meaning:"不久、片刻之后。"},{term:"丧",pinyin:["sàng"],meaning:"使失去、损丧。"},{term:"吾存",pinyin:["wú","cún"],meaning:"自身所存、生命安顿等，具体所指有解释空间。"},{term:"存存",pinyin:["cún","cún"],meaning:"使所存者得以存，前后用法不同。"},{term:"未始",pinyin:["wèi","shǐ"],meaning:"未曾、从未。"}]}),t[39]||(t[39]=n("h3",{id:"核心句引读-10",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-10","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"国家与君位的存亡，不足以穷尽一个人的所存",subtitle:"转换判断尺度，不是抹去现实亡国的损失。",lines:[{text:"楚王左右曰「凡亡」者三。",tone:"反复",guide:"侍从三次说凡亡，形成强烈的重复压力，也可读出威慑、轻侮的意味。但原文没有交代亡国原因、谁发动征服，或凡君是否刚在席间失国，不能补成已知的完整战争经过。"},{text:"凡之亡也，不足以丧吾存。",tone:"分辨",guide:"凡君拒绝把国家之亡直接等同自身全部丧失。吾存可联系生命的真实安顿、德或不被国位穷尽的自身理解。不是说国土、人民与生活条件不重要，也不保证亡国不会造成实际痛苦。这里首先是对身份与生命完全同一的拒绝。"},{text:"则楚之存不足以存存。",tone:"反问",guide:"若凡国的亡不足以决定全部所存，那么楚国仍存，也不足以自动保证同一尺度上的真实安顿。凡君由失者转向得者：拥有大国，并不自动完成一个人的生命。存存应联系保全所存理解，不必把它化成现代形而上学中未经说明的存在本体。"},{text:"凡未始亡而楚未始存也。",tone:"收束",guide:"最后的悖论依赖前面已经转换的尺度。并非否认凡国灭亡、楚国尚存，而是说这些政治事实不足以独自决定生命所存。不能据此总结土地、军队、人民都只是虚假外壳，更不能将亡国者的苦难视作无关紧要。"}]}),t[40]||(t[40]=i(`<h3 id="与开篇回环" tabindex="-1">与开篇回环 <a class="header-anchor" href="#与开篇回环" aria-label="Permalink to &quot;与开篇回环&quot;">​</a></h3><p>开篇魏文侯说：</p><blockquote><p><strong>夫魏真为我累耳！</strong></p></blockquote><p>篇末凡君说：</p><blockquote><p><strong>凡之亡也，不足以丧吾存。</strong></p></blockquote><p>一处从<strong>拥有国家</strong>感到牵累，一处在<strong>国家失去</strong>时拒绝让其穷尽自身。</p><p>中间的儒服、爵禄、令尹得失，也持续追问：</p><p><strong>身份、势位与可见标志，是否足以决定一个人的全部成就？</strong></p><p>这不等于外在条件毫无意义，而是限制它们的决定权。</p><p><strong>有国不必然成其德，失国也不必然尽其所存。</strong></p><h2 id="脉络逻辑链" tabindex="-1">脉络逻辑链 <a class="header-anchor" href="#脉络逻辑链" aria-label="Permalink to &quot;脉络逻辑链&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段·开篇：田子方与魏文侯</span></span>
<span class="line"><span>    称道切当 → 追问其师</span></span>
<span class="line"><span>    → 人貌天虚、缘而葆真、清而容物</span></span>
<span class="line"><span>    → 文侯重新衡量所学与君位</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第2段·相见：温伯雪子</span></span>
<span class="line"><span>    礼义熟练 → 未必知人心</span></span>
<span class="line"><span>    仪节齐备 → 未必真实相契</span></span>
<span class="line"><span>    → 目击而道存，不必再加言声</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第3段·追随：颜渊与仲尼</span></span>
<span class="line"><span>    能随言辩 → 难以复制整体作用</span></span>
<span class="line"><span>    → 老师也在流逝</span></span>
<span class="line"><span>    → 不追执故吾，保留活的相通</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第4段·本源：孔子见老聃</span></span>
<span class="line"><span>    静止外貌 → 游心于物之初</span></span>
<span class="line"><span>    → 生成、消长、常与变</span></span>
<span class="line"><span>    → 不把自然之德误作额外加工</span></span>
<span class="line"><span>    → 发吾覆，打开原有认识</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第5段·标志：儒服与儒道</span></span>
<span class="line"><span>    穿着其服 → 不必知其道</span></span>
<span class="line"><span>    → 判断回到所知与所能</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第6段·短章：百里奚与有虞氏</span></span>
<span class="line"><span>    爵禄、死生不入于心</span></span>
<span class="line"><span>    → 仍能认真做事、感发他人</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第7段·创作：宋元君与画史</span></span>
<span class="line"><span>    作画准备 → 不足独证真画者</span></span>
<span class="line"><span>    → 从容舒放，不被场面拘束</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第8段·治理：文王与臧丈人</span></span>
<span class="line"><span>    常钓 → 任用的现实两难</span></span>
<span class="line"><span>    → 不以偏令与自据功德治理</span></span>
<span class="line"><span>    → 辞去、无闻，因时而应</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第9段·技艺：列御寇射箭</span></span>
<span class="line"><span>    熟练稳定 → 临渊受扰</span></span>
<span class="line"><span>    → 技艺、心神与条件的关联</span></span>
<span class="line"><span>    → 不射之射的理想</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第10段·得失：孙叔敖三为三去</span></span>
<span class="line"><span>    职位来去 → 不以得失穷尽自己</span></span>
<span class="line"><span>    → 真人之神不受阻染</span></span>
<span class="line"><span>    → 给予他人，自身更充实</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第11段·收束：楚王与凡君</span></span>
<span class="line"><span>    国之亡 → 不尽吾存</span></span>
<span class="line"><span>    国之存 → 不保证所存</span></span>
<span class="line"><span>    → 外在势位不能独定生命成就</span></span></code></pre></div><p>**全篇主线：**真实成就不止于言说、仪节、服饰与势位；它需要在相见、学习、创作、治理和得失中落实，又不能被已经显露的形式穷尽。</p><p>这是一条阅读线索，不是原文明列的十一级修养阶梯。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问-《田子方》的核心问题是什么" tabindex="-1">第一问：《田子方》的核心问题是什么？ <a class="header-anchor" href="#第一问-《田子方》的核心问题是什么" aria-label="Permalink to &quot;第一问：《田子方》的核心问题是什么？&quot;">​</a></h3><blockquote><p><strong>「缘而葆真，清而容物。」</strong></p></blockquote><p>开篇提出全德之君子，但全篇并不只描写封闭的「内心」。</p><p>它连续检验：</p><ul><li>一个真实的人如何与他人相见。</li><li>学生如何追随正在变化的老师。</li><li>技艺如何进入不拘束的状态。</li><li>治理如何面对现实条件。</li><li>人如何面对名位、得失与存亡。</li></ul><p>因而，核心问题可以表述为：</p><p><strong>人的真实成就，怎样不被可见形式代替，又怎样仍在实际关系与行动中发生？</strong></p><p>「缘而葆真」保留顺应与根本。</p><p>「清而容物」保留清明与应接。</p><p>不是以内心否定一切外界，也不是以外在标准完全塑造自身，而是使二者不再割裂。</p><h3 id="第二问-全篇是不是反对语言、礼仪、服饰和技术" tabindex="-1">第二问：全篇是不是反对语言、礼仪、服饰和技术？ <a class="header-anchor" href="#第二问-全篇是不是反对语言、礼仪、服饰和技术" aria-label="Permalink to &quot;第二问：全篇是不是反对语言、礼仪、服饰和技术？&quot;">​</a></h3><p>不是。</p><p>原文的结构恰好保留它们：</p><table tabindex="0"><thead><tr><th>所检验者</th><th>原文保留的一面</th></tr></thead><tbody><tr><td>言说</td><td>谿工的论说切当受到称赞</td></tr><tr><td>问答</td><td>老聃用长篇说明回应孔子</td></tr><tr><td>礼仪</td><td>问题在是否知人心，不只在动作有无</td></tr><tr><td>服饰</td><td>真儒者仍然穿儒服</td></tr><tr><td>技艺</td><td>列御寇原先的熟练并未被抹除</td></tr><tr><td>治理</td><td>百里奚、孙叔敖与臧丈人都曾承担政事</td></tr></tbody></table><p>被限制的是：</p><p><strong>以形式当作充分证明。</strong></p><p><strong>以技巧当作处处可靠的保证。</strong></p><p><strong>以已得成就当作固定身份。</strong></p><p>同理，「目击而道存」不能变成凭第一印象判定一切；「不射之射」不能变成拒绝训练；「不修」也不能变成停止反省。</p><h3 id="第三问-得失非我、凡亡不丧吾存-是否意味着现实损失不重要" tabindex="-1">第三问：得失非我、凡亡不丧吾存，是否意味着现实损失不重要？ <a class="header-anchor" href="#第三问-得失非我、凡亡不丧吾存-是否意味着现实损失不重要" aria-label="Permalink to &quot;第三问：得失非我、凡亡不丧吾存，是否意味着现实损失不重要？&quot;">​</a></h3><blockquote><p><strong>「得失之非我。」</strong></p><p><strong>「凡之亡也，不足以丧吾存。」</strong></p></blockquote><p>两句都在限制<strong>外在得失对自身的全部定义</strong>，而非取消得失事实。</p><p>职位失去，可能影响收入、职责与生活。</p><p>国家灭亡，更可能影响人民、安全与秩序。</p><p>这些都不能因为精神安顿而被否认。</p><p>但它们也不必直接等同：</p><p><strong>我全部无价值。</strong></p><p><strong>我的生命已经没有任何可继续之处。</strong></p><p>本篇可以启发的，是同时承认：</p><p><strong>损失真实，需要处理。</strong></p><p><strong>自身不必被损失穷尽。</strong></p><p>这也不要求人立刻停止悲伤，更不能用「你应该超脱」责备正在受苦的人。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><blockquote><p>以下为现代引申，不是原文已经提出的心理、管理或艺术理论，也不是普遍免患的方法。</p></blockquote><h3 id="关于表达-正确的话-需要回到真实关系中" tabindex="-1">关于表达：正确的话，需要回到真实关系中 <a class="header-anchor" href="#关于表达-正确的话-需要回到真实关系中" aria-label="Permalink to &quot;关于表达：正确的话，需要回到真实关系中&quot;">​</a></h3><p>知道礼貌用语、熟悉沟通流程，可以帮助交往，但仍须理解：</p><ul><li>对方此刻需要说明，还是需要倾听？</li><li>我是否总把自己放在指导、规劝的位置？</li><li>合规的表达，是否遮住了真实问题？</li><li>我是否允许对方不同意自己的理解？</li></ul><p>「知人心」不宜变成声称自己能读懂别人，而应包含询问、倾听与修正。</p><p><strong>懂得一套说法，不等于已经理解眼前的人。</strong></p><h3 id="关于学习-不要只收藏老师的旧答案" tabindex="-1">关于学习：不要只收藏老师的旧答案 <a class="header-anchor" href="#关于学习-不要只收藏老师的旧答案" aria-label="Permalink to &quot;关于学习：不要只收藏老师的旧答案&quot;">​</a></h3><p>第三段提醒：老师也在变化。</p><p>学习可以从模仿开始，但还需：</p><ul><li>理解某个答案面对的条件。</li><li>分辨哪些原则可以迁移。</li><li>知道什么时候需要新判断。</li><li>允许自己提问与核验。</li></ul><p><strong>重复得像，不一定理解得深。</strong></p><p>同时，也不应以「不能执旧迹」为由，拒绝记忆、基础练习与已有知识。</p><h3 id="关于创作-减少展示压力-不是取消专业标准" tabindex="-1">关于创作：减少展示压力，不是取消专业标准 <a class="header-anchor" href="#关于创作-减少展示压力-不是取消专业标准" aria-label="Permalink to &quot;关于创作：减少展示压力，不是取消专业标准&quot;">​</a></h3><p>解衣般礴可启发一种创作条件：</p><p><strong>暂时松开“我必须看起来像创作者”的压力。</strong></p><p>对一些人而言，这可能意味着：</p><ul><li>先写粗稿，再整理形式。</li><li>在安全、私密的空间试错。</li><li>把评价与初步生成分开。</li><li>不让工具、仪式和人设占满注意。</li></ul><p>但作品仍需要修改，合作仍需要守约，专业仍需要训练。</p><p><strong>自在的状态与可靠的成果，需要共同检验。</strong></p><h3 id="关于工作-有目标-但不把全部价值押在结果上" tabindex="-1">关于工作：有目标，但不把全部价值押在结果上 <a class="header-anchor" href="#关于工作-有目标-但不把全部价值押在结果上" aria-label="Permalink to &quot;关于工作：有目标，但不把全部价值押在结果上&quot;">​</a></h3><p>常钓不能直接要求现代人做事毫无目标。</p><p>可以保留：</p><ul><li>工作目标。</li><li>时间安排。</li><li>对结果的复核。</li><li>对影响的承担。</li></ul><p>同时减少另一层负担：</p><p><strong>每件事都必须证明我成功、贤明或值得被承认。</strong></p><p>不被结果穷尽，与不关心结果，是两回事。</p><h3 id="关于恐惧-先处理危险-再谈状态" tabindex="-1">关于恐惧：先处理危险，再谈状态 <a class="header-anchor" href="#关于恐惧-先处理危险-再谈状态" aria-label="Permalink to &quot;关于恐惧：先处理危险，再谈状态&quot;">​</a></h3><p>列御寇临渊的故事不可作为冒险训练。</p><p>当身体发出强烈警报时，先考虑：</p><ul><li>环境是否真的危险。</li><li>是否应该停止、撤离或寻求保护。</li><li>能否在安全条件下逐步训练。</li><li>当前任务是否超出能力与准备。</li></ul><p>恐惧可能干扰表现，也可能正确提示风险。</p><p><strong>神气稳定不能替代安全措施。</strong></p><h3 id="关于身份-职位可以改变-自身不只是一张名片" tabindex="-1">关于身份：职位可以改变，自身不只是一张名片 <a class="header-anchor" href="#关于身份-职位可以改变-自身不只是一张名片" aria-label="Permalink to &quot;关于身份：职位可以改变，自身不只是一张名片&quot;">​</a></h3><p>孙叔敖与凡君的故事，可用于检查：</p><ul><li>我是否只能通过职位确认价值？</li><li>他人的贵贱判断是否占满注意？</li><li>某个身份失去后，哪些能力与关系仍可继续？</li><li>我需要怎样的实际支持，才能重新安排生活？</li></ul><p>不以职位立己，并不意味着失业无所谓；它允许人在承认困难时，不把自己全部判为失败。</p><h3 id="关于给予-充实可以增长-资源仍然有限" tabindex="-1">关于给予：充实可以增长，资源仍然有限 <a class="header-anchor" href="#关于给予-充实可以增长-资源仍然有限" aria-label="Permalink to &quot;关于给予：充实可以增长，资源仍然有限&quot;">​</a></h3><p>「既以与人己愈有」可联系分享经验、建立信任与共同成长。</p><p>但给予也可能耗费：</p><ul><li>时间。</li><li>金钱。</li><li>注意力。</li><li>情绪与身体精力。</li></ul><p>因此，真实的给予应包含边界与恢复。</p><p><strong>因帮助而更充实，不意味着永远不会疲惫，也不意味着必须持续牺牲。</strong></p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>出处</th><th>核心含义</th></tr></thead><tbody><tr><td>全德之君子</td><td>第1段</td><td>生命与德行成就完整，不止于论说切当</td></tr><tr><td>人貌而天虚</td><td>第1段</td><td>有人的形貌，而精神虚静自然</td></tr><tr><td>缘而葆真</td><td>第1段</td><td>顺循情势而不失根本</td></tr><tr><td>清而容物</td><td>第1段</td><td>清明自持而仍能应接他物</td></tr><tr><td>正容以悟之</td><td>第1段</td><td>自身端正状态能够使人感发</td></tr><tr><td>知人心</td><td>第2段</td><td>规范熟练之外，对具体之人的理解</td></tr><tr><td>目击而道存</td><td>第2段</td><td>相见之际已有真实相契</td></tr><tr><td>不可以容声</td><td>第2段</td><td>此际言声未必需要加入，表达亦有其限度</td></tr><tr><td>不言而信</td><td>第3段</td><td>信任不只由语言建立</td></tr><tr><td>不比而周</td><td>第3段</td><td>不刻意结附而能周遍相合</td></tr><tr><td>哀莫大于心死</td><td>第3段</td><td>心的死滞，联系失去随化应接活力理解</td></tr><tr><td>故吾</td><td>第3段</td><td>已经过去的样貌、言行与表现</td></tr><tr><td>不忘者存</td><td>第3段</td><td>不被旧迹穷尽的根本或相通，所指有争议</td></tr><tr><td>游心于物之初</td><td>第4段</td><td>游于万物生成变化的根本</td></tr><tr><td>至美至乐</td><td>第4段</td><td>通达根本而自在与之相游</td></tr><tr><td>大常</td><td>第4段</td><td>变化中仍保有的根本条件</td></tr><tr><td>贵在于我</td><td>第4段</td><td>所贵不完全由外在依凭决定</td></tr><tr><td>不修而自然</td><td>第4段</td><td>不将德的通达理解为额外加工与装饰</td></tr><tr><td>醯鸡、发吾覆</td><td>第4段</td><td>承认原有认识受遮限，并使尺度打开</td></tr><tr><td>儒服与儒道</td><td>第5段</td><td>标志不等于真实理解与能力</td></tr><tr><td>爵禄不入于心</td><td>第6段</td><td>不以爵位俸禄支配心神</td></tr><tr><td>死生不入于心</td><td>第6段</td><td>不被存亡之虑拘系，非无视生命</td></tr><tr><td>解衣般礴</td><td>第7段</td><td>舒放而不受展示场面拘束</td></tr><tr><td>常钓</td><td>第8段</td><td>不以求得、求用固着其活动，句意有讨论</td></tr><tr><td>典法无更，偏令无出</td><td>第8段</td><td>不以频繁改法、私意偏令显示治理</td></tr><tr><td>循斯须</td><td>第8段</td><td>顺循一时情势，代词所指有不同解释</td></tr><tr><td>射之射与不射之射</td><td>第9段</td><td>熟练操作与不受射意拘系的区别</td></tr><tr><td>神气不变</td><td>第9段</td><td>精神不轻易失其根本的理想表达</td></tr><tr><td>得失之非我</td><td>第10段</td><td>得失非全由己，也不穷尽自身</td></tr><tr><td>既以与人己愈有</td><td>第10段</td><td>给予可使生命成就更充实，非资源数量保证</td></tr><tr><td>吾存</td><td>第11段</td><td>不被国位完全穷尽的生命所存</td></tr><tr><td>凡未始亡而楚未始存</td><td>第11段</td><td>政治存亡不足独定真实所存</td></tr></tbody></table><h3 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>句子</th><th>出处</th><th>主题</th></tr></thead><tbody><tr><td>称道数当，故无择称之</td><td>第1段</td><td>言说切当的长处</td></tr><tr><td>人貌而天虚，缘而葆真，清而容物</td><td>第1段</td><td>真实与应接相通</td></tr><tr><td>正容以悟之，使人之意也消</td><td>第1段</td><td>自身状态的感发作用</td></tr><tr><td>夫魏真为我累耳</td><td>第1段</td><td>君位与牵累</td></tr><tr><td>明乎礼义而陋于知人心</td><td>第2段</td><td>规范不代替理解</td></tr><tr><td>目击而道存矣，亦不可以容声矣</td><td>第2段</td><td>相见与言说的限度</td></tr><tr><td>不言而信，不比而周</td><td>第3段</td><td>整体作用不止于显设手段</td></tr><tr><td>哀莫大于心死，而人死亦次之</td><td>第3段</td><td>心的死滞</td></tr><tr><td>丘以是日徂</td><td>第3段</td><td>老师亦在流逝</td></tr><tr><td>虽忘乎故吾，吾有不忘者存</td><td>第3段</td><td>旧迹之外的相通</td></tr><tr><td>吾游心于物之初</td><td>第4段</td><td>游心于生成根本</td></tr><tr><td>得至美而游乎至乐，谓之至人</td><td>第4段</td><td>至人的命名</td></tr><tr><td>行小变而不失其大常</td><td>第4段</td><td>常与变</td></tr><tr><td>贵在于我而不失于变</td><td>第4段</td><td>不以外得穷尽所贵</td></tr><tr><td>至人之于德也，不修而物不能离焉</td><td>第4段</td><td>德的自然作用</td></tr><tr><td>有其道者，未必为其服也</td><td>第5段</td><td>成就不必依标志</td></tr><tr><td>为其服者，未必知其道也</td><td>第5段</td><td>标志不足以证明成就</td></tr><tr><td>百里奚爵禄不入于心，故饭牛而牛肥</td><td>第6段</td><td>不受名位拘系而仍办事</td></tr><tr><td>有虞氏死生不入于心，故足以动人</td><td>第6段</td><td>不以存亡之虑拘心</td></tr><tr><td>解衣般礴裸</td><td>第7段</td><td>创作中的舒放</td></tr><tr><td>可矣，是真画者也</td><td>第7段</td><td>从状态识人</td></tr><tr><td>其钓莫钓……常钓也</td><td>第8段</td><td>不固着求得</td></tr><tr><td>典法无更，偏令无出</td><td>第8段</td><td>治理不强作</td></tr><tr><td>彼直以循斯须也</td><td>第8段</td><td>因时而应</td></tr><tr><td>是射之射，非不射之射也</td><td>第9段</td><td>技艺与执持</td></tr><tr><td>挥斥八极，神气不变</td><td>第9段</td><td>精神通达的理想</td></tr><tr><td>吾以为得失之非我也</td><td>第10段</td><td>不以得失立己</td></tr><tr><td>何暇至乎人贵人贱哉</td><td>第10段</td><td>不被评价占满</td></tr><tr><td>既以与人己愈有</td><td>第10段</td><td>给予与充实</td></tr><tr><td>凡之亡也，不足以丧吾存</td><td>第11段</td><td>国亡不尽自身</td></tr><tr><td>楚之存不足以存存</td><td>第11段</td><td>国存不保证生命成就</td></tr></tbody></table><h2 id="与前篇的呼应" tabindex="-1">与前篇的呼应 <a class="header-anchor" href="#与前篇的呼应" aria-label="Permalink to &quot;与前篇的呼应&quot;">​</a></h2><blockquote><p>以下为问题与表达的对读，不据此断定篇章之间的单向引用、写作先后或严格境界等级。</p></blockquote><table tabindex="0"><thead><tr><th>前篇表达</th><th>《田子方》对应</th><th>可连读的问题</th><th>需要保留的区别</th></tr></thead><tbody><tr><td>《山木》形莫若缘，情莫若率</td><td>缘而葆真，清而容物</td><td>顺循而不失真实</td><td>不必分成方法与更高境界</td></tr><tr><td>《山木》虚己以游世</td><td>人貌而天虚</td><td>不以自我执持占满自身</td><td>不是现实免伤承诺</td></tr><tr><td>《山木》鲁国独非君之皮邪</td><td>夫魏真为我累耳</td><td>国家与君位也会造成牵累</td><td>不直接导出放弃一切治理</td></tr><tr><td>《山木》行贤而去自贤</td><td>不言而信、真画者</td><td>实践不必依靠自我加冕</td><td>不等于沉默、脱衣必然有德</td></tr><tr><td>《山木》晏然体逝</td><td>丘以是日徂</td><td>相交者与生命都在变化</td><td>不直接推成个人永生</td></tr><tr><td>《山木》腾猿之喻</td><td>列御寇临渊</td><td>表现受具体条件影响</td><td>心神稳定不消除危险</td></tr><tr><td>《山木》贫非惫</td><td>孙叔敖三为三去</td><td>外貌、职位不尽自身价值</td><td>不否认现实困顿</td></tr><tr><td>《达生》其德全矣</td><td>全德之君子</td><td>成就不止于外显的强势</td><td>不把德解释成使万物臣服的控制力</td></tr><tr><td>《达生》梓庆与专一</td><td>解衣般礴、不射之射</td><td>技艺与注意、状态相接</td><td>不取消训练与专业判断</td></tr><tr><td>《达生》忘适之适</td><td>常钓、循斯须</td><td>行动不必叠加过度自我监控</td><td>不等于没有任何目的</td></tr><tr><td>《应帝王》用心若镜</td><td>清而容物、得失非我</td><td>应接而不固藏外得</td><td>不等于遗忘责任</td></tr><tr><td>《养生主》薪火之喻</td><td>吾有不忘者存</td><td>形迹变化与根本相续</td><td>两处均不直接作为灵魂不灭的证明</td></tr></tbody></table><h3 id="出处辨明" tabindex="-1">出处辨明 <a class="header-anchor" href="#出处辨明" aria-label="Permalink to &quot;出处辨明&quot;">​</a></h3><p><strong>「目击而道存」出于本篇《田子方》的温伯雪子段。</strong></p><p>《山木》的第二段是市南宜僚与鲁侯、虚舟故事，并没有这句话。</p><p>对读时可以联系真实相处与非功利关系，但不能把相近主题写成相同原文。</p><h2 id="十一段·一句话回顾" tabindex="-1">十一段·一句话回顾 <a class="header-anchor" href="#十一段·一句话回顾" aria-label="Permalink to &quot;十一段·一句话回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段落</th><th>主要人物</th><th>阅读落点</th></tr></thead><tbody><tr><td>第1段</td><td>田子方、魏文侯、东郭顺子</td><td>顺循而葆真，清明而容物</td></tr><tr><td>第2段</td><td>温伯雪子、孔子</td><td>礼仪熟练不等于知人心，相见可有真实相契</td></tr><tr><td>第3段</td><td>颜渊、孔子</td><td>学习不能只追逐已经过去的老师</td></tr><tr><td>第4段</td><td>孔子、老聃</td><td>游心于生成根本，不把德误作额外装饰</td></tr><tr><td>第5段</td><td>庄子、鲁哀公</td><td>服饰标志不能替代所知与所能</td></tr><tr><td>第6段</td><td>百里奚、有虞氏</td><td>不以名位存亡拘心，仍能做事与感发</td></tr><tr><td>第7段</td><td>宋元君、画史</td><td>创作不只在准备姿态，更在不拘束的状态</td></tr><tr><td>第8段</td><td>文王、臧丈人</td><td>不据功、不强作，治理仍须因时而应</td></tr><tr><td>第9段</td><td>列御寇、伯昏无人</td><td>熟练、心神与环境之间仍需分辨</td></tr><tr><td>第10段</td><td>肩吾、孙叔敖、孔子</td><td>职位得失不穷尽自己，给予可以使生命更充实</td></tr><tr><td>第11段</td><td>楚王、凡君</td><td>国家与势位的存亡不足独定生命所存</td></tr></tbody></table><h2 id="一句话读懂《田子方》" tabindex="-1">一句话读懂《田子方》 <a class="header-anchor" href="#一句话读懂《田子方》" aria-label="Permalink to &quot;一句话读懂《田子方》&quot;">​</a></h2><blockquote><p><strong>「缘而葆真，清而容物。」</strong></p></blockquote><p>能顺循变化，却不让自己完全由变化定义。</p><p>能保持清明，却不因此封闭于他人。</p><p>言语、礼仪、技艺与身份都可以有作用，但不能代替真实成就，也不能将它穷尽。</p><p><strong>真实不只是藏在内心的东西，而要在相见、学习、做事与给予中显出。</strong></p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>开篇文侯重新看待：</p><blockquote><p><strong>我所学的。</strong></p><p><strong>我所拥有的魏国。</strong></p></blockquote><p>篇末凡君重新看待：</p><blockquote><p><strong>我已经失去的凡国。</strong></p><p><strong>楚王仍然拥有的楚国。</strong></p></blockquote><p>从拥有到失去，全篇都在限制一个等同：</p><p><strong>我有这些，所以我才是我。</strong></p><p><strong>我失去这些，所以我全部消失。</strong></p><p>读完可以继续问：</p><p><strong>哪些外在标志确实帮助我生活，却已经被我当成全部价值？</strong></p><p><strong>当我不再依靠它们证明自己时，我仍能怎样学习、行动、关怀与承担？</strong></p><p>这不必用一句「我已经超脱」回答。</p><p>能继续分辨、继续应接，正是没有把心固定在旧迹之中。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《庄子·外篇·田子方》</li><li>对读篇目：《庄子·养生主》《应帝王》《达生》《山木》</li></ul><blockquote><p>**整理说明：**本页依据提供的原文与注解整理。疑难字句保留解释空间；古音、异文、人物身份及具体制度解释，宜依项目统一底本与注本进一步校定。现代启发为引申，不代替原文训释。</p></blockquote>`,126))])}}});export{F as __pageData,L as default};
